const articleMarkupBase = "<header><div class=\"wrap\"><div class=\"eyebrow\">Label Moto · Guide pratique</div><h1>Entretien moto : 10 vérifications à faire soi-même</h1><p class=\"lead\">Pas besoin d’être mécanicien pour repérer une chaîne trop détendue, un pneu usé ou une fuite suspecte.</p><p class=\"lead\">Dans ce guide, découvre <strong>10 vérifications essentielles pour entretenir ta moto</strong>, avec des illustrations pour savoir où regarder et reconnaître les premiers signes d’usure.</p><p class=\"lead\">L’objectif : apprendre à contrôler les points importants de ta moto en toute sécurité, sans te lancer dans des réparations qui nécessitent l’intervention d’un professionnel.</p><p class=\"lead\"><strong>Ces mêmes vérifications peuvent aussi t’aider à repérer certains défauts lorsque tu examines une moto d’occasion avant de l’acheter.</strong></p></div></header><main>\n<div class=\"lm-mobile-reference\"><div class=\"lm-mobile-main\">\n<section aria-label=\"Sommaire interactif des contrôles\" class=\"lm-sommaire\">\n<h2>Les 10 contrôles moto à faire soi-même</h2>\n<p>7 rubriques pour retrouver les 10 vérifications. Sélectionne un point sur la moto.</p>\n<div class=\"lm-hero-visual\">\n<img alt=\"Moto roadster noire sans marque, sommaire interactif des contrôles\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5.webp\"/>\n<svg aria-hidden=\"true\" class=\"lm-map-connectors\" preserveaspectratio=\"none\" viewbox=\"0 0 100 100\"><polyline points=\"12,12 18,22 34,37\"></polyline><circle cx=\"34\" cy=\"37\" r=\"0.85\"></circle><polyline points=\"88,12 80,28 69,55\"></polyline><circle cx=\"69\" cy=\"55\" r=\"0.85\"></circle><polyline points=\"13,55 29,57 48,64\"></polyline><circle cx=\"48\" cy=\"64\" r=\"0.85\"></circle><polyline points=\"17,87 22,79 29,72\"></polyline><circle cx=\"29\" cy=\"72\" r=\"0.85\"></circle><polyline points=\"50,87 64,70 72,70\"></polyline><circle cx=\"72\" cy=\"70\" r=\"0.85\"></circle><polyline points=\"50,87 36,76 24,73\"></polyline><circle cx=\"24\" cy=\"73\" r=\"0.85\"></circle><polyline points=\"83,87 80,78\"></polyline><circle cx=\"80\" cy=\"78\" r=\"0.85\"></circle></svg><a aria-label=\"Aller à la rubrique 05 : Batterie\" class=\"lm-perimeter-btn lm-top-left\" href=\"#controle-05\" style=\"left:12%;top:8%\">Batterie</a><a aria-label=\"Aller à la rubrique 07 : Avant de partir\" class=\"lm-perimeter-btn lm-top-mid\" href=\"#controle-07\" style=\"left:50%;top:8%\">Avant de partir</a><a aria-label=\"Aller à la rubrique 06 : Fourche\" class=\"lm-perimeter-btn lm-top-right\" href=\"#controle-06\" style=\"left:88%;top:8%\">Fourche</a><a aria-label=\"Aller à la rubrique 04 : Niveaux\" class=\"lm-perimeter-btn lm-mid-left\" href=\"#controle-04\" style=\"left:13%;top:55%\">Niveaux</a><a aria-label=\"Aller à la rubrique 01 : Kit chaîne\" class=\"lm-perimeter-btn lm-bottom-left\" href=\"#controle-01\" style=\"left:17%;top:91%\">Kit chaîne</a><a aria-label=\"Aller à la rubrique 03 : Freins\" class=\"lm-perimeter-btn lm-bottom-mid\" href=\"#controle-03\" style=\"left:50%;top:91%\">Freins</a><a aria-label=\"Aller à la rubrique 02 : Pneus\" class=\"lm-perimeter-btn lm-bottom-right\" href=\"#controle-02\" style=\"left:83%;top:91%\">Pneus</a></div>\n</section><div class=\"intro\"><h2>Comment vérifier sa moto soi-même en toute sécurité ?</h2><p>Installe la moto sur un sol stable, coupe le moteur et laisse refroidir les pièces chaudes. Garde tes doigts loin de la chaîne, protège pneus et freins des produits d’entretien et utilise la notice de ta moto pour les valeurs exactes.</p><div class=\"alert\"><strong>À savoir :</strong> ces vérifications visuelles ne remplacent ni les opérations d’entretien prévues par le constructeur ni un diagnostic professionnel.</div></div><details class=\"section\" id=\"controle-01\" open=\"\"><summary><span class=\"num\">01</span><span><h2>Chaîne moto : vérifier la tension, l’usure et le graissage</h2><span class=\"sub\">Inspecter, nettoyer et lubrifier la transmission</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Kit chaîne — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7c665d4329f05cc7-desktop-square.webp\"/><button aria-controls=\"p01-0\" aria-label=\"Ouvrir : État de la chaîne\" class=\"hotspot\" onclick=\"showPopup('p01-0')\" style=\"--x:19%;--y:39%\">1</button><div aria-label=\"État de la chaîne\" class=\"popup\" id=\"p01-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-0')\">×</button><img alt=\"Illustration : État de la chaîne\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-9598ba108629b2a6-desktop-square.webp\"/><div class=\"content\"><h3>Comment reconnaître une chaîne moto usée ?</h3><p>Cherche la corrosion, les points durs et les maillons abîmés. Une chaîne qui accroche ou présente des points durs persistants doit être examinée.</p></div></div><button aria-controls=\"p01-1\" aria-label=\"Ouvrir : Tension et débattement\" class=\"hotspot\" onclick=\"showPopup('p01-1')\" style=\"--x:52%;--y:41%\">2</button><div aria-label=\"Tension et débattement\" class=\"popup\" id=\"p01-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-1')\">×</button><img alt=\"Illustration : Tension et débattement\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-d19eb30c989c5787-desktop-square.webp\"/><div class=\"content\"><h3>Comment vérifier la tension de chaîne moto ?</h3><p>Vérifie le débattement au point indiqué par le constructeur. Fais tourner la roue à la main, moteur coupé, pour rechercher le point le plus tendu.</p></div></div><button aria-controls=\"p01-2\" aria-label=\"Ouvrir : Nettoyage et lubrification\" class=\"hotspot\" onclick=\"showPopup('p01-2')\" style=\"--x:36%;--y:67%\">3</button><div aria-label=\"Nettoyage et lubrification\" class=\"popup\" id=\"p01-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-2')\">×</button><img alt=\"Illustration : Nettoyage et lubrification\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-17feab5c52ca26b0-desktop-square.webp\"/><div class=\"content\"><h3>Comment nettoyer et graisser une chaîne moto ?</h3><p>Utilise un produit compatible et protège le pneu et les freins des projections. N’approche jamais les doigts d’une transmission en mouvement.</p></div></div><button aria-controls=\"p01-3\" aria-label=\"Ouvrir : Couronne et pignon\" class=\"hotspot\" onclick=\"showPopup('p01-3')\" style=\"--x:62%;--y:73%\">4</button><div aria-label=\"Couronne et pignon\" class=\"popup\" id=\"p01-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-3')\">×</button><img alt=\"Illustration : Couronne et pignon\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-adfb2bdc7802bdb9-desktop-square.webp\"/><div class=\"content\"><h3>Comment repérer l’usure du pignon et de la couronne ?</h3><p>Repère les dents anormalement pointues, crochues ou endommagées. Fais vérifier le kit complet si l’usure est marquée.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(1,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-1\">1 / 5</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(1,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-1\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 5\" class=\"technical-card\"><h4>Repère les signes d’usure</h4><p>Inspecte les maillons, les joints et les dents de la couronne. Une plaque fissurée, un maillon grippé ou des dents très crochues signalent une usure anormale. Une chaîne fissurée impose l’immobilisation.</p></article><article aria-label=\"Conseil 2 sur 5\" class=\"technical-card\"><h4>Vérifie la tension</h4><p>Une chaîne trop tendue sollicite la transmission ; trop lâche, elle peut battre ou dérailler. Mesure sa flèche selon la méthode et la valeur indiquées par le constructeur.</p></article><article aria-label=\"Conseil 3 sur 5\" class=\"technical-card\"><h4>Nettoie sans abîmer les joints</h4><p>Utilise un nettoyant compatible avec les chaînes à joints et une brosse adaptée. Moteur coupé : ne fais jamais tourner la roue au moteur pour nettoyer la chaîne. Protège pneus et freins.</p></article><article aria-label=\"Conseil 4 sur 5\" class=\"technical-card\"><h4>Lubrifie correctement</h4><p>Sur une chaîne nécessitant une lubrification, applique un produit adapté sur la face intérieure, sans excès. Respecte son temps d’adhérence avant de rouler.</p></article><article aria-label=\"Conseil 5 sur 5\" class=\"technical-card\"><h4>Quand remplacer le kit ?</h4><p>Points durs persistants, allongement excessif ou dents très usées ? Fais contrôler chaîne, pignon et couronne ensemble. Un nettoyage ne répare pas une transmission en fin de vie.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 5</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-1\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/brosse-chaine.png\" alt=\"Brosse souple pour chaîne — visuel générique\" loading=\"lazy\" /></div><strong>Brosse souple pour chaîne</strong><span>Pour retirer les saletés sans agresser les joints.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/2447-moto-2024-brosse-chaine-tete-3-faces-3352341721241.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Brosse 3 faces</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/brosse-de-chaine\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · Brosse de chaîne</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/nettoyant-chaine.png\" alt=\"Nettoyant compatible chaînes à joints — visuel générique\" loading=\"lazy\" /></div><strong>Nettoyant compatible chaînes à joints</strong><span>Évite les solvants inadaptés.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motul.com/en-FR/products/23001\" target=\"_blank\" rel=\"noopener noreferrer external\">Motul · MC Care C1</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/chain-cleaner\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · Chain Cleaner</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lubrifiant-chaine.png\" alt=\"Lubrifiant pour chaîne moto — visuel générique\" loading=\"lazy\" /></div><strong>Lubrifiant pour chaîne moto</strong><span>Choisis un produit compatible avec ta transmission.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motul.com/fr-FR/products/23301?product=MOTUL+MC+CARE+C2+CHAIN+LUBE+ROAD\" target=\"_blank\" rel=\"noopener noreferrer external\">Motul · MC Care C2 Road</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/x-trem-chain-road\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · X-Trem Chain Road</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/mesure-chaine.png\" alt=\"Règle graduée — visuel générique\" loading=\"lazy\" /></div><strong>Règle graduée</strong><span>Pour mesurer le débattement selon la notice.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motionpro.com/product/08-0674\" target=\"_blank\" rel=\"noopener noreferrer external\">Motion Pro · SlackSetter Pro</a><a class=\"lm-fabricant-link\" href=\"https://www.beta-tools.com/en/products/measuring-and-marking-tools/measuring-tapes-and-folding-rules/measuring-tapes-shock-resistant-bi-material-abs-casings-steel-tapes-precision-class-ii.html\" target=\"_blank\" rel=\"noopener noreferrer external\">BETA · Mètre 1692</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/bequille-arriere.png\" alt=\"Béquille centrale ou d’atelier adaptée — visuel générique\" loading=\"lazy\" /></div><strong>Béquille centrale ou d’atelier adaptée</strong><span>Seulement si la moto et la méthode de contrôle le permettent.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://lightech.it/en/yamaha_r9_2026/modular-iron-rear-stand-with-rollers-and-4-wheels.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Lightech · RSF039R (vérifier adaptation)</a><a class=\"lm-fabricant-link\" href=\"https://www.oxfordproducts.com/oxford-premium-rear-paddock-stand-ox281.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Oxford · Premium Rear OX281 (vérifier adaptation)</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Sur une moto stable, moteur coupé, observe les maillons, la tension et les dents. La valeur de jeu et la méthode de mesure dépendent du modèle : consulte la notice.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Sur une moto stable, moteur coupé, observe les maillons, la tension et les dents. La valeur de jeu et la méthode de mesure dépendent du modèle : consulte la notice.</p></div></div></details><details class=\"section\" id=\"controle-02\" open=\"\"><summary><span class=\"num\">02</span><span><h2>Pneus moto : contrôler la pression, l’usure et le marquage</h2><span class=\"sub\">Usure, dommages, marquages et pression</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Pneus — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-b5a7faa1faad60b6-desktop-square.webp\"/><button aria-controls=\"p02-0\" aria-label=\"Ouvrir : Dommages visibles\" class=\"hotspot\" onclick=\"showPopup('p02-0')\" style=\"--x:70%;--y:24%\">1</button><div aria-label=\"Dommages visibles\" class=\"popup\" id=\"p02-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-0')\">×</button><img alt=\"Dommages : coupure, hernie, craquelures\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-1e8f1a81ce46d380-desktop-square.webp\"/><div class=\"content\"><h3>Pneu moto abîmé : coupures, hernies et craquelures</h3><p>Coupure, hernie ou craquelures importantes : évite de rouler et fais contrôler ou remplacer le pneu.</p></div></div><button aria-controls=\"p02-1\" aria-label=\"Ouvrir : Usure anormale\" class=\"hotspot\" onclick=\"showPopup('p02-1')\" style=\"--x:72%;--y:48%\">2</button><div aria-label=\"Usure anormale\" class=\"popup\" id=\"p02-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-1')\">×</button><img alt=\"Usures anormales : centre, épaules et facettes\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-5392edd72f2006ca-desktop-square.webp\"/><div class=\"content\"><h3>Usure irrégulière d’un pneu moto : les signes à repérer</h3><p>Contrôle le témoin d’usure et les différences entre centre, épaules et facettes. Une usure irrégulière mérite un diagnostic.</p></div></div><button aria-controls=\"p02-2\" aria-label=\"Ouvrir : Lire le marquage\" class=\"hotspot\" onclick=\"showPopup('p02-2')\" style=\"--x:43%;--y:44%\">3</button><div aria-label=\"Lire le marquage\" class=\"popup\" id=\"p02-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-2')\">×</button><img alt=\"Marquage du pneu : 120/70 R17 58W\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-7fdbe8c96b5b2fe9-desktop-square.webp\"/><div class=\"content\"><h3>Comment lire les dimensions et indices d’un pneu moto ?</h3><p>Exemple : 120/70 R17 58W. Vérifie les dimensions et les indices homologués pour ta moto.</p><p data-lm-mobile-twi=\"20261114\" style=\"margin-top:10px!important\"><strong>Et le TWI ?</strong> C’est l’abréviation de <em>Tread Wear Indicator</em> (témoin d’usure). Sur le flanc du pneu, le repère TWI indique où trouver les petites barrettes dans les rainures. Lorsque la gomme atteint leur niveau, il faut remplacer le pneu.</p></div></div><button aria-controls=\"p02-3\" aria-label=\"Ouvrir : Pression\" class=\"hotspot\" onclick=\"showPopup('p02-3')\" style=\"--x:39%;--y:76%\">4</button><div aria-label=\"Pression\" class=\"popup\" id=\"p02-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-3')\">×</button><img alt=\"Pression à froid : valve et manomètre\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-1780908908502bcd-desktop-square.webp\"/><div class=\"content\"><h3>Comment contrôler la pression des pneus moto à froid ?</h3><p>Mesure à froid avec un manomètre. La valeur affichée est illustrative : utilise la pression prescrite par le constructeur, selon la charge.</p></div></div><button aria-controls=\"p02-4\" aria-label=\"Ouvrir : date de fabrication DOT\" class=\"hotspot\" onclick=\"showPopup('p02-4')\" style=\"--x:17%;--y:64%\">5</button><div aria-label=\"Date de fabrication DOT\" class=\"popup dot-popup\" id=\"p02-4\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-4')\">×</button><div class=\"dot-inner\"><img alt=\"Marquage photographié 4020 sur le flanc d’un pneu\" class=\"dot-photo\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-59d72c0f052f2669-desktop-square.webp\"/><div class=\"dot-copy\"><h3>DOT pneu moto : comment lire la date de fabrication ?</h3><div class=\"dot-values\"><div><strong>40</strong><span>40ᵉ semaine</span></div><div><strong>20</strong><span>Année 2020</span></div></div><p><strong>4020</strong> signifie que ce pneu a été fabriqué durant la 40ᵉ semaine de 2020.</p><p>Lors d’un achat d’occasion, vérifie le code de date sur les deux pneus, leur état et les éventuelles craquelures. La date seule ne fixe pas une péremption.</p></div></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(2,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-2\">1 / 5</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(2,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-2\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 5\" class=\"technical-card\"><h4>Contrôle la pression à froid</h4><p>Un pneu peut sembler bien gonflé alors qu’il manque de pression. Utilise un manomètre et les valeurs de ta moto adaptées à la charge, pas la pression maximale inscrite sur le pneu.</p></article><article aria-label=\"Conseil 2 sur 5\" class=\"technical-card\"><h4>Mesure l’usure</h4><p>Repère les témoins TWI et mesure la profondeur des rainures avec une jauge. Vérifie aussi les exigences réglementaires applicables : le témoin seul ne remplace pas une mesure.</p></article><article aria-label=\"Conseil 3 sur 5\" class=\"technical-card\"><h4>Inspecte flancs et bande de roulement</h4><p>Cherche hernies, fissures profondes, coupures ou objets plantés. Une hernie ou une carcasse visible impose de ne pas rouler. Ne retire pas un objet incrusté sans évaluation.</p></article><article aria-label=\"Conseil 4 sur 5\" class=\"technical-card\"><h4>Reconnais l’usure irrégulière</h4><p>Un pneu aplati au centre peut modifier le comportement de la moto. Une usure anormale peut aussi révéler un souci de pression, de charge ou de suspension.</p></article><article aria-label=\"Conseil 5 sur 5\" class=\"technical-card\"><h4>Comprends la date DOT</h4><p>Les quatre chiffres du code de date indiquent la semaine et l’année de fabrication. L’âge seul ne suffit pas : état, stockage et recommandations du fabricant comptent aussi.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 4</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-2\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/manometre.png\" alt=\"Manomètre fiable — visuel générique\" loading=\"lazy\" /></div><strong>Manomètre fiable</strong><span>Pour contrôler la pression à froid.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.oxfordproducts.com/oxford-tyre-gauge-pro-dial-type-0-60psi-ox750.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Oxford · Tyre Gauge Pro OX750</a><a class=\"lm-fabricant-link\" href=\"https://slime.com/products/digital-tire-gauge-5-150-psi\" target=\"_blank\" rel=\"noopener noreferrer external\">Slime · Digital Tire Gauge 20017</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/jauge-pneus.png\" alt=\"Jauge de profondeur de sculpture — visuel générique\" loading=\"lazy\" /></div><strong>Jauge de profondeur de sculpture</strong><span>Pour mesurer les rainures, pas seulement regarder les témoins.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.clas.com/fr/jauge-de-profondeur-pour-pneus-ac-4951.html\" target=\"_blank\" rel=\"noopener noreferrer external\">CLAS · AC4951</a><a class=\"lm-fabricant-link\" href=\"https://www.lasertools.co.uk/pis/4262_PIS.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Laser Tools · Jauge numérique 4262</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" /></div><strong>Lampe d’inspection</strong><span>Pour examiner flancs, entailles et craquelures.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon doux — visuel générique\" loading=\"lazy\" /></div><strong>Chiffon doux</strong><span>Pour nettoyer une zone de marquage sans l’abîmer.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Regarde toute la bande de roulement et les flancs, puis contrôle la pression à froid. Le marquage illustré est un exemple : il ne remplace pas les spécifications de ta moto.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Regarde toute la bande de roulement et les flancs, puis contrôle la pression à froid. Le marquage illustré est un exemple : il ne remplace pas les spécifications de ta moto.</p></div></div></details><details class=\"section\" id=\"controle-03\" open=\"\"><summary><span class=\"num\">03</span><span><h2>Freins moto : vérifier les plaquettes et les disques</h2><span class=\"sub\">Plaquettes, disques et signes d’alerte</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Freins — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-8630811240c2e647-desktop-square.webp\"/><button aria-label=\"État du disque\" class=\"hotspot\" onclick=\"showPopup('p03-1')\" style=\"--x:58%;--y:76%\" type=\"button\">2</button><button aria-label=\"Plaquettes de frein\" class=\"hotspot\" onclick=\"showPopup('p03-0')\" style=\"--x:35%;--y:50%\" type=\"button\">1</button><button aria-label=\"Observer sans démontage\" class=\"hotspot\" onclick=\"showPopup('p03-3')\" style=\"--x:65%;--y:35%\" type=\"button\">4</button><button aria-label=\"Plaquette neuve et usée\" class=\"hotspot\" onclick=\"showPopup('p03-2')\" style=\"--x:33%;--y:67%\" type=\"button\">3</button><div aria-label=\"Épaisseur des plaquettes\" class=\"popup\" id=\"p03-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-0')\">×</button><img alt=\"Gros plan sur la garniture et les témoins d’usure, sans roue en arrière-plan\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-4dc2934722736ed2-desktop-square.webp\"/><div class=\"content\"><h3>Comment vérifier l’usure des plaquettes de frein moto ?</h3><p>Repère la garniture et le témoin d’usure, lorsqu’il est visible. Si la garniture est très mince ou si tu as un doute, fais vérifier les freins.</p></div></div><div aria-label=\"État des disques\" class=\"popup\" id=\"p03-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-1')\">×</button><img alt=\"Illustration : État des disques\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-ea4ab82b988441f4-desktop-square.webp\"/><div class=\"content\"><h3>Disque de frein moto : repérer les signes d’usure</h3><p>Recherche rayures profondes, fissures, voile ou changement anormal d’aspect. La limite d’épaisseur est propre au disque.</p></div></div><div aria-label=\"Plaquette neuve et usée\" class=\"popup\" id=\"p03-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-2')\">×</button><img alt=\"Plaquette neuve et usée\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-980819ef458a6c1b-desktop-square.webp\"/><div class=\"content\"><h3>Plaquette de frein moto neuve ou usée : comparer la garniture</h3><p>Compare l’épaisseur de la garniture de friction (zone orange), sans la confondre avec le support métallique. Respecte la limite indiquée par le constructeur.</p></div></div><div aria-label=\"Observer sans démontage\" class=\"popup\" id=\"p03-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-3')\">×</button><img alt=\"Observer sans démontage\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-50d01a587d721610-desktop-square.webp\"/><div class=\"content\"><h3>Comment voir les plaquettes de frein sans démontage ?</h3><p>Regarde par l’ouverture de l’étrier pour repérer la garniture entre le support métallique et le disque. Selon le modèle, l’accès peut être limité : fais vérifier les deux plaquettes si tu ne peux pas les voir correctement.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(3,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-3\">1 / 10</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(3,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-3\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 10\" class=\"technical-card\"><h4>Identifie la garniture</h4><p>Une plaquette comprend un support métallique et une garniture de friction. C’est la garniture qui s’use : ne confonds pas son épaisseur avec celle de la plaquette entière.</p></article><article aria-label=\"Conseil 2 sur 10\" class=\"technical-card\"><h4>Observe les deux plaquettes</h4><p>Vérifie les faces intérieure et extérieure du disque : elles peuvent s’user différemment. La limite d’épaisseur dépend du fabricant.</p></article><article aria-label=\"Conseil 3 sur 10\" class=\"technical-card\"><h4>Inspecte le disque</h4><p>De fines traces circulaires peuvent être normales. Fissures, rainures profondes ou usure importante nécessitent un contrôle. MIN TH indique l’épaisseur minimale lorsqu’elle est marquée.</p></article><article aria-label=\"Conseil 4 sur 10\" class=\"technical-card\"><h4>Reconnais un freinage anormal</h4><p>Levier soudainement mou, course excessive, vibrations inhabituelles ou bruit métallique persistant : plusieurs causes sont possibles. Perte d’efficacité ou fuite : ne roule pas.</p></article><article aria-label=\"Conseil 5 sur 10\" class=\"technical-card\"><h4>Quand consulter ?</h4><p>Si les plaquettes approchent leur limite ou si le disque semble endommagé, fais vérifier le système. L’inspection visuelle est accessible ; la réparation exige des compétences adaptées.</p></article><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4>Repère les réservoirs</h4><p>Celui du frein avant se trouve souvent près du levier droit ; celui de l’arrière près du cadre. Ils peuvent posséder un hublot ou une paroi translucide.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4>Lis le niveau sans ouvrir</h4><p>Sur une moto droite et selon la position indiquée dans la notice, regarde si le liquide se situe entre les repères MIN et MAX. Un niveau bas peut être lié à l’usure des plaquettes, mais aussi à une fuite : fais contrôler si tu as un doute. N’ouvre pas le bocal pour une simple vérification.</p></article><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4>Comprends la baisse du niveau</h4><p>Quand les plaquettes s’usent, les pistons avancent. Le liquide descend alors dans le réservoir : ce n’est pas forcément une fuite. Évite tout appoint au hasard.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4>Couleur et type de liquide</h4><p>La couleur ne mesure pas la teneur en eau. Respecte les intervalles constructeur. DOT 3, 4 et 5.1 sont glycolés ; DOT 5 est à base de silicone et ne doit pas être confondu avec DOT 5.1.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4>Reconnais une anomalie</h4><p>Levier spongieux, course inhabituelle, fuite ou baisse rapide du niveau : fais contrôler le circuit. En cas de défaut de freinage, ne roule pas. N’ouvre pas le réservoir pour une simple inspection.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 2</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-3\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" /></div><strong>Lampe d’inspection</strong><span>Pour observer l’épaisseur des garnitures et les disques.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon propre — visuel générique\" loading=\"lazy\" /></div><strong>Chiffon propre</strong><span>Pour nettoyer les surfaces extérieures accessibles, sans contaminer les freins.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Un freinage spongieux, un bruit inhabituel, des vibrations ou une fuite sont des raisons de faire contrôler rapidement le système. Ne démonte pas les freins sans compétence adaptée.</p><p><strong>Faire contrôler l’usure des freins :</strong> si tu ne parviens pas à voir l’épaisseur de la garniture ou si le disque présente des rainures, fais contrôler tes freins par un professionnel. Il pourra mesurer l’épaisseur des plaquettes et du disque, puis comparer les résultats aux limites indiquées par le constructeur.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Un freinage spongieux, un bruit inhabituel, des vibrations ou une fuite sont des raisons de faire contrôler rapidement le système. Ne démonte pas les freins sans compétence adaptée.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/map\">Faire contrôler tes freins par un professionnel ↗</a></p></div></div></details><details class=\"section\" id=\"controle-04\" open=\"\"><summary><span class=\"num\">04</span><span><h2>Niveaux moto : vérifier l’huile, les liquides et l’embrayage</h2><span class=\"sub\">Freins, embrayage, refroidissement et huile moteur</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Moto roadster noire sans marque sur fond neutre, points de contrôle interactifs\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5-desktop-square.webp\"/><button aria-controls=\"p04-0\" aria-label=\"Ouvrir : Embrayage\" class=\"hotspot\" onclick=\"showPopup('p04-0')\" style=\"--x:80%;--y:29.8%\">1</button><div aria-label=\"Embrayage\" class=\"popup\" id=\"p04-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-0')\">×</button><img alt=\"Embrayage\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-28ce7aa24d44125c-desktop-square.webp\"/><div class=\"content\"><h3>Embrayage moto : câble ou hydraulique, que vérifier ?</h3><p>Selon la moto, l’embrayage fonctionne par câble ou par circuit hydraulique. Un modèle à câble n’a pas de réservoir de liquide d’embrayage.</p></div></div><button aria-controls=\"p04-1\" aria-label=\"Ouvrir : Liquide de frein\" class=\"hotspot\" onclick=\"showPopup('p04-1')\" style=\"--x:55%;--y:29.8%\">2</button><div aria-label=\"Liquide de frein\" class=\"popup\" id=\"p04-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-1')\">×</button><img alt=\"Liquide de frein\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-57975ddafe14a7ac-desktop-square.webp\"/><div class=\"content\"><h3>Liquide de frein moto : où trouver les bocaux et lire le niveau ?</h3><p>Contrôle les repères MIN/MAX des réservoirs avant et arrière, moto dans la position prévue par la notice. Une baisse de niveau peut accompagner l’usure des plaquettes ou signaler une fuite.</p></div></div><button aria-controls=\"p04-2\" aria-label=\"Ouvrir : Liquide de refroidissement\" class=\"hotspot\" onclick=\"showPopup('p04-2')\" style=\"--x:66%;--y:59.8%\">3</button><div aria-label=\"Liquide de refroidissement\" class=\"popup\" id=\"p04-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-2')\">×</button><img alt=\"Liquide de refroidissement\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7c9c444dc2001731-desktop-square.webp\"/><div class=\"content\"><h3>Liquide de refroidissement moto : contrôler le niveau à froid</h3><p>Moteur froid, vérifie le vase d’expansion entre MIN et MAX selon la notice. N’ouvre jamais un bouchon de circuit sous pression à chaud.</p></div></div><button aria-controls=\"p04-3\" aria-label=\"Ouvrir : Huile moteur\" class=\"hotspot\" onclick=\"showPopup('p04-3')\" style=\"--x:43%;--y:59.0%\">4</button><div aria-label=\"Huile moteur\" class=\"popup\" id=\"p04-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-3')\">×</button><img alt=\"Huile moteur\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-cc1948992f27ba22.webp\"/><div class=\"content\"><h3>Niveau d’huile moto : comment lire le hublot ou la jauge ?</h3><p>Contrôle par hublot ou jauge selon la procédure du constructeur : moto droite ou sur béquille adaptée, moteur froid ou après attente prescrite.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(4,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-4\">1 / 10</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(4,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-4\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 10\" class=\"technical-card\"><h4>Huile moteur : repère le niveau</h4><p>Repère le hublot ou la jauge et suis exactement la procédure de ta notice : position de la moto, température du moteur et délai d’attente peuvent varier selon le modèle.</p></article><article aria-label=\"Conseil 2 sur 10\" class=\"technical-card\"><h4>Huile : interprète et réagis</h4><p>Lis la plage indiquée et évite le surremplissage. Une couleur sombre seule ne prouve pas une huile usée ; émulsion persistante, particules métalliques, baisse rapide ou voyant de pression imposent un contrôle.</p></article><article aria-label=\"Conseil 3 sur 10\" class=\"technical-card\"><h4>Refroidissement : contrôle à froid</h4><p>Si ta moto possède un vase d’expansion, vérifie les repères MIN/MAX à froid, dans la position prévue. N’ouvre jamais le bouchon d’un circuit chaud ou sous pression.</p></article><article aria-label=\"Conseil 4 sur 10\" class=\"technical-card\"><h4>Refroidissement : repère les anomalies</h4><p>Surveille les fuites, dépôts secs, durites abîmées et baisses répétées. Respecte la spécification du liquide, pas seulement sa couleur. En cas de surchauffe, arrête-toi en sécurité.</p></article><article aria-label=\"Conseil 5 sur 10\" class=\"technical-card\"><h4>Freins : localise les réservoirs</h4><p>Le bocal de frein avant se trouve généralement au guidon, près du levier droit. Celui du frein arrière est souvent situé sous la selle, derrière un cache latéral ou à proximité de l’amortisseur arrière, parfois près du maître-cylindre et de la pédale de frein. Leur emplacement varie selon la moto : consulte la notice constructeur pour les localiser et lire les niveaux dans la position prescrite, sans ouvrir les réservoirs.</p></article><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4>Freins : comprends le niveau</h4><p>Un niveau qui baisse peut accompagner l’usure des plaquettes, sans être nécessairement une fuite. Contrôle l’état des plaquettes et recherche toute baisse anormale avant d’envisager un appoint.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4>Freins : liquide et signes d’alerte</h4><p>La couleur ne permet pas de juger l’humidité du liquide. Respecte le type et l’intervalle constructeur. Levier spongieux, fuite ou freinage anormal : ne roule pas et fais contrôler le circuit.</p></article><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4>Embrayage : câble ou hydraulique ?</h4><p>Identifie le système de ta moto : câble avec gaine, ou circuit hydraulique avec maître-cylindre. Les contrôles et les fluides éventuels ne sont pas interchangeables.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4>Embrayage : vérifie la commande</h4><p>Pour un câble, observe garde, gaine et brins effilochés selon la notice. Pour un circuit hydraulique, recherche les fuites et une modification de sensation au levier ; respecte le fluide prescrit.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4>Embrayage : reconnais un défaut</h4><p>Patinage à l’accélération, point mort difficile ou moto qui cherche à avancer levier serré peuvent révéler un défaut de commande ou d’embrayage : fais diagnostiquer si le phénomène persiste.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 3</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-4\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe et chiffon propre — visuel générique\" loading=\"lazy\" /></div><strong>Lampe et chiffon propre</strong><span>Pour lire les repères de niveau.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/entonnoir.png\" alt=\"Entonnoir propre adapté — visuel générique\" loading=\"lazy\" /></div><strong>Entonnoir propre adapté</strong><span>Uniquement si un appoint est prévu par la notice.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.drapertools.com/product/56141/pvc-flexible-funnel/\" target=\"_blank\" rel=\"noopener noreferrer external\">Draper · 56141</a><a class=\"lm-fabricant-link\" href=\"https://www.pressol.com/resources/portalmedia/media/16745499_20190723_HST_GB.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Pressol · Entonnoir 02 662 (PDF)</a></div></div></li><li><strong>Liquides aux spécifications constructeur</strong><span>Ne mélange pas des produits non compatibles.</span></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Quatre vérifications regroupées sur une seule moto. Les positions montrées sont indicatives : chaque modèle place ses réservoirs et ses repères différemment.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Quatre vérifications regroupées sur une seule moto. Les positions montrées sont indicatives : chaque modèle place ses réservoirs et ses repères différemment.</p></div></div></details><details class=\"section\" id=\"controle-05\" open=\"\"><summary><span class=\"num\">05</span><span><h2>Batterie moto : repérer l’oxydation et les signes de faiblesse</h2><span class=\"sub\">Oxydation, déformation et témoin éventuel</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Batterie — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/batterie-principale-desktop-desktop-square.webp\"/><button aria-controls=\"p05-location\" aria-label=\"Localiser la batterie\" class=\"hotspot\" onclick=\"showPopup('p05-location')\" style=\"--x:68%;--y:24%\" type=\"button\">1</button><div aria-label=\"Localiser la batterie\" class=\"popup\" id=\"p05-location\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p05-location')\">×</button><figure class=\"location-figure\" style=\"display:block!important;width:100%!important;max-width:100%!important;margin:0 0 9px!important;padding:0!important;\"><figcaption style=\"display:block;margin:0 0 6px;font-weight:700;color:#b84b00;\">Sous la selle</figcaption><img alt=\"Photographie originale : batterie située sous la selle\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7822f0eeb9123667-desktop-square.webp\" style=\"display:block!important;width:100%!important;max-width:100%!important;height:auto!important;max-height:none!important;object-fit:cover!important;margin:0!important;border-radius:10px;\"/></figure><figure class=\"location-figure\" style=\"display:block!important;width:100%!important;max-width:100%!important;margin:0 0 9px!important;padding:0!important;\"><figcaption style=\"display:block;margin:0 0 6px;font-weight:700;color:#b84b00;\">Derrière un cache latéral</figcaption><img alt=\"Photographie originale : batterie située derrière un cache latéral\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-6139ad2a6de45990.webp\" style=\"display:block!important;width:100%!important;max-width:100%!important;height:auto!important;max-height:none!important;object-fit:cover!important;margin:0!important;border-radius:10px;\"/></figure></div><button aria-controls=\"p05-etat\" aria-label=\"Ouvrir : Oxydation et boîtier gonflé\" class=\"hotspot\" data-lm-battery-cta2-position=\"20261114\" data-lm-battery-cta2-sibling=\"20261114\" onclick=\"showPopup('p05-etat')\" style=\"--x:28%;--y:73%\" type=\"button\">2</button><div aria-label=\"Les signes d’une batterie à surveiller\" class=\"popup\" id=\"p05-etat\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p05-etat')\">×</button><img alt=\"Batterie moto : cosse oxydée et boîtier gonflé\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-d0d441c8e24aa386-desktop-square.webp\"/><div class=\"content\"><h3>Les signes d’une batterie à surveiller</h3><p>Observe les cosses oxydées, les câbles abîmés, un boîtier gonflé ou fissuré et toute fuite. Un témoin éventuel ne suffit pas à diagnostiquer l’état de la batterie.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(5,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-5\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(5,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-5\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Reconnais une batterie faible</h4><p>Démarreur lent, clic au démarrage ou voyants qui faiblissent : la batterie peut manquer de charge. Un mauvais contact ou un défaut du démarreur peut produire les mêmes symptômes.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Observe son état extérieur</h4><p>Si elle est accessible sans intervention, recherche un boîtier gonflé ou fissuré, une fuite ou une corrosion importante. Une batterie endommagée ne doit pas être mise en charge.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Pourquoi se décharge-t-elle ?</h4><p>Trajets courts, immobilisation, vieillissement ou défaut de recharge : plusieurs causes existent. Un USB ou un accessoire alimenté en permanence peut aussi consommer du courant à l’arrêt.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Recharger ou remplacer ?</h4><p>Une batterie déchargée n’est pas forcément hors service. Un professionnel peut tester sa capacité et le circuit de charge. Pour l’hivernage, le maintien de charge doit être adapté à la batterie.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 3</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-5\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" /></div><strong>Lampe d’inspection</strong><span>Pour observer le boîtier et les connexions accessibles.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li><strong>Chargeur de maintien compatible</strong><span>À choisir selon la technologie de la batterie.</span></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/gants-nitrile.png\" alt=\"Gants et lunettes de protection — visuel générique\" loading=\"lazy\" /></div><strong>Gants et lunettes de protection</strong><span>Pour toute intervention autorisée par le fabricant.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Gants nitrile (lunettes à choisir séparément)</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.ansell.com/fr/fr/products/touchntuff-92-600\" target=\"_blank\" rel=\"noopener noreferrer external\">Ansell · TouchNTuff 92-600</a><a class=\"lm-fabricant-link\" href=\"https://www.showagroup.com/eu-en/shop/7500pf/\" target=\"_blank\" rel=\"noopener noreferrer external\">SHOWA · 7500PF</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Inspecte visuellement la batterie et ses connexions, moteur coupé. Cherche les traces d’oxydation, un boîtier gonflé, des fuites ou des câbles abîmés. Le témoin visuel, lorsqu’il existe, ne suffit pas à diagnostiquer toutes les batteries.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Inspecte visuellement la batterie et ses connexions, moteur coupé. Cherche les traces d’oxydation, un boîtier gonflé, des fuites ou des câbles abîmés. Le témoin visuel, lorsqu’il existe, ne suffit pas à diagnostiquer toutes les batteries.</p></div></div></details><details class=\"section\" id=\"controle-06\" open=\"\"><summary><span class=\"num\">06</span><span><h2>Fourche moto : reconnaître une fuite de joint spi</h2><span class=\"sub\">Comparer une fourche sèche et une fuite probable</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Fourche et joints spi — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-62d964a9681690c5-desktop-square.webp\"/><button aria-controls=\"p06-0\" aria-label=\"Ouvrir : Tube piqué ou rayé\" class=\"hotspot\" onclick=\"showPopup('p06-0')\" style=\"--x:52%;--y:29%\">1</button><div aria-label=\"Tube piqué ou rayé\" class=\"popup\" id=\"p06-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p06-0')\">×</button><img alt=\"Tube piqué ou rayé\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-da04df55dc6a3957-desktop-square.webp\"/><div class=\"content\"><h3>Tube de fourche piqué ou rayé : quels signes surveiller ?</h3><p>Des piqûres, rayures ou traces de corrosion sur la zone de coulissement peuvent détériorer le joint spi. Fais contrôler la fourche si le chrome est endommagé.</p></div></div><button aria-label=\"Ouvrir : cache-poussière craquelé et trace grasse\" class=\"hotspot\" onclick=\"showPopup('p06-joint')\" style=\"--x:76%;--y:54%\" type=\"button\">2</button><div aria-label=\"Inspection du cache-poussière et du joint\" class=\"popup\" id=\"p06-joint\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p06-joint')\">×</button><img alt=\"Photographie originale : cache-poussière de fourche craquelé et traces grasses autour du joint\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-e83f8ef1c7816175-desktop-square.webp\"/><div class=\"content\"><h3>Joint spi et cache-poussière de fourche : craquelures et traces d’huile</h3><p>Observe les craquelures du caoutchouc, le dépôt noir et les traces grasses autour du tube. Ces signes ne prouvent pas à eux seuls une fuite du joint spi. Si de l’huile réapparaît sur le tube, fais contrôler la fourche, surtout si elle risque d’atteindre le frein ou le pneu.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(6,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-6\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(6,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-6\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Comprends les deux joints</h4><p>Le cache-poussière protège la zone coulissante des saletés. Le joint spi, situé derrière, retient l’huile de fourche. Ce sont deux éléments distincts.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Poussière ou fuite ?</h4><p>Un tube poussiéreux n’est pas forcément défectueux. Une trace grasse persistante ou une coulure près du joint peut signaler une fuite.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Observe les tubes</h4><p>Rayures, impacts, corrosion ou caoutchouc détérioré peuvent favoriser une fuite. Un choc important peut aussi endommager la suspension sans fuite immédiate.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Quand faire réparer ?</h4><p>Une fuite confirmée nécessite un diagnostic. Si l’huile atteint le pneu ou les freins, n’utilise pas la moto. Le remplacement d’un joint spi est une intervention technique.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"accessory-counter\">1 / 3</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-6\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" /></div><strong>Lampe d’inspection</strong><span>Pour repérer les traces grasses et les impacts.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon doux non pelucheux — visuel générique\" loading=\"lazy\" /></div><strong>Chiffon doux non pelucheux</strong><span>Pour essuyer délicatement la zone accessible.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Passe en revue les tubes et la zone des joints. Une trace d’huile répétée peut indiquer une fuite ; ne roule pas si de l’huile risque d’atteindre le frein ou le pneu.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Passe en revue les tubes et la zone des joints. Une trace d’huile répétée peut indiquer une fuite ; ne roule pas si de l’huile risque d’atteindre le frein ou le pneu.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/map\">Trouver un atelier pour contrôler la fourche ↗</a></p></div></div></details><details class=\"section\" id=\"controle-07\" open=\"\"><summary><span class=\"num\">07</span><span><h2>Avant de partir : les 4 dernières vérifications rapides</h2><span class=\"sub\">Quatre contrôles rapides, comme un tour de moto avant de rouler</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Moto roadster noire sans marque sur fond neutre, points de contrôle interactifs\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5-desktop-square.webp\"/><button aria-controls=\"p07-1\" aria-label=\"Ouvrir : Éclairage et signalisation\" class=\"hotspot\" onclick=\"showPopup('p07-1')\" style=\"--x:82%;--y:27%\">1</button><div aria-label=\"Éclairage et signalisation\" class=\"popup\" id=\"p07-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-1')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Éclairage et signalisation\" src=\"/images/entretien-moto-guide/controle-21fff2c40492c790-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Comment vérifier les feux stop et clignotants moto seul ?</h3><p>Teste séparément les deux commandes de frein pour vérifier le feu stop. Contrôle aussi les feux avant, les clignotants et l’éclairage de plaque.</p><p style=\"margin-top:12px\">Seul, utilise le reflet sur un mur ou une vitrine, ou filme l’arrière de la moto avec un téléphone posé sur un support stable.</p></div></div><button aria-controls=\"p07-2\" aria-label=\"Ouvrir : Commandes et câbles\" class=\"hotspot\" onclick=\"showPopup('p07-2')\" style=\"--x:53%;--y:27%\">2</button><div aria-label=\"Commandes et câbles\" class=\"popup\" id=\"p07-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-2')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Commandes et câbles\" src=\"/images/entretien-moto-guide/controle-518d1180b32daf55-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Accélérateur et commandes moto : vérifier le retour et les points durs</h3><p>À l’arrêt, vérifie que la poignée d’accélérateur revient librement et que les leviers et pédales fonctionnent sans point dur.</p><p style=\"margin-top:12px\">Tourne doucement le guidon de butée à butée, moteur coupé : aucune commande ni aucun câble ne doit accrocher ou se tendre anormalement.</p></div></div><button aria-controls=\"p07-3\" aria-label=\"Ouvrir : Fuites et fixations\" class=\"hotspot\" onclick=\"showPopup('p07-3')\" style=\"--x:43%;--y:66%\">3</button><div aria-label=\"Fuites et fixations\" class=\"popup\" id=\"p07-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-3')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Fuites et fixations\" src=\"/images/entretien-moto-guide/controle-b88ac487c4590184-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Fuite d’huile moto : vérifier les traces au sol et les fixations</h3><p>Regarde sous la moto et autour du moteur, des durites et des suspensions. Une trace fraîche de liquide doit être identifiée.</p><p style=\"margin-top:12px\">Une tache au sol ne suffit pas à identifier le liquide. Si tu suspectes une fuite de frein ou une fuite importante, ne prends pas la route.</p></div></div><button aria-controls=\"p07-4\" aria-label=\"Ouvrir : Dernier tour de moto\" class=\"hotspot\" onclick=\"showPopup('p07-4')\" style=\"--x:30%;--y:43%\">4</button><div aria-label=\"Dernier tour de moto\" class=\"popup\" id=\"p07-4\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-4')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Dernier tour de moto\" src=\"/images/entretien-moto-guide/controle-38a00b9d519a0972-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Contrôle avant de rouler : rétroviseurs, bagages et voyants</h3><p>Vérifie les rétroviseurs, les bagages, les éléments visibles mal fixés et les éventuels voyants d’alerte.</p><p style=\"margin-top:12px\">Avant de démarrer, assure-toi qu’aucun objet ne gêne la direction, les roues, les commandes ou la transmission.</p></div></div></div><details class=\"technical-detail\" open=\"\"><summary>Conseils pratiques · faire défiler</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(7,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-7\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(7,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-7\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Éclairage et signalisation</h4><p>Teste le feu stop avec chaque commande. Seul, utilise un reflet sur un mur ou une vidéo sur support stable.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Commandes et câbles</h4><p>Vérifie à l’arrêt le retour libre de l’accélérateur, les leviers et les pédales, sans point dur.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Fuites et fixations</h4><p>Cherche les traces fraîches sous le moteur et près des durites et suspensions. Fais identifier toute fuite suspecte.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Dernier tour de moto</h4><p>Contrôle les rétroviseurs, les bagages, les éléments pendants et les témoins inhabituels.</p></article></div></details><details class=\"accessory-strip accessory-details\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\">‹</button><span class=\"accessory-counter\">1 / 3</span><button aria-label=\"Accessoire suivant\" data-direction=\"1\">›</button></div><ul class=\"accessory-list\" id=\"accessory-carousel-7\" tabindex=\"0\"><li><strong>Smartphone et support stable</strong><span>Pour filmer le feu stop lorsque tu es seul.</span></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" /></div><strong>Lampe d’inspection</strong><span>Pour observer les zones sombres autour du moteur.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon propre — visuel générique\" loading=\"lazy\" /></div><strong>Chiffon propre</strong><span>Pour distinguer une trace ancienne d’une trace fraîche, sans toucher aux pièces chaudes.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details><details class=\"additional-info\"><summary>Informations et précautions complémentaires</summary><p>Effectue ces contrôles moto immobilisée, sur un sol stable. Le fonctionnement des feux varie selon les modèles : certains nécessitent le moteur en marche. Pour tester les feux seul, ne laisse pas tourner le moteur dans un espace fermé.</p><p>Si une commande accroche, si un témoin critique reste allumé ou si tu suspectes une fuite de frein, fais contrôler la moto avant de rouler.</p></details></div><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Avant de partir : feux, commandes, fuites visibles et derniers éléments à sécuriser. Sélectionne un point orange pour afficher la méthode.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/info/premiere-moto-accessoires-indispensables-conseils-a2\">Voir les accessoires indispensables à moto ↗</a></p></div></div></details><section class=\"lm-ending lm-ending-final\" aria-label=\"Conclusion de l’article\"><span class=\"lm-final-kicker\">À retenir</span><h2>Inspecter sa moto, c’est déjà mieux la connaître</h2><p>Tu n’as pas besoin d’être mécanicien pour repérer une chaîne anormale, un pneu abîmé, une fuite ou une commande qui fonctionne mal. Le bon réflexe, c’est d’observer régulièrement ta moto et de suivre sa notice, sans improviser de réparation.</p><p>Ces vérifications ne remplacent pas l’entretien prévu par le constructeur. Si un élément de sécurité te semble douteux, ne prends pas de risque : fais contrôler ta moto avant de repartir.</p><p class=\"lm-ending-occasion\" data-lm-occasion-conclusion=\"20261114\">Ces dix contrôles te serviront aussi si tu envisages une moto d’occasion : ils donnent une première idée de son état avant l’achat, sans remplacer l’essai, l’historique d’entretien ni l’avis d’un professionnel.</p><a class=\"lm-occasion-cta\" data-lm-occasion-cta=\"20261114\" href=\"https://labelmoto.fr/info/achat-moto-occasion-guide-complet-pour-eviter-les-pieges\"><span class=\"lm-occasion-cta-text\"><span class=\"lm-occasion-cta-kicker\">Guide d’achat moto d’occasion</span><strong class=\"lm-occasion-cta-title\">Les pièges à éviter avant d’acheter</strong></span><span class=\"lm-occasion-cta-arrow\" aria-hidden=\"true\">→</span></a><div class=\"lm-ending-actions\"><a class=\"lm-primary-link\" href=\"https://labelmoto.fr/map\">Trouver un professionnel sur la carte</a><a class=\"lm-secondary-link\" href=\"https://labelmoto.fr/info/premiere-moto-accessoires-indispensables-conseils-a2\">Découvrir les accessoires indispensables</a></div></section>\n<section class=\"lm-final-faq\" data-lm-final-faq=\"20261114\" aria-labelledby=\"lm-final-faq-mobile\"><div class=\"lm-faq-heading\"><span class=\"lm-final-kicker\">Recherche rapide</span><h2 id=\"lm-final-faq-mobile\">Questions fréquentes</h2><p>Un doute sur un contrôle ? Retrouve l’essentiel en quelques secondes.</p></div><div class=\"lm-faq-list\"><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Faut-il faire les dix contrôles avant chaque trajet ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Pas forcément en détail. Avant de partir, vérifie au minimum l’état visible des pneus, l’absence de fuite, le fonctionnement des feux et des commandes. Pour la pression, la chaîne et les niveaux, suis les indications de ta notice, notamment avant un long trajet ou après une immobilisation.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Peut-on vérifier soi-même la tension de sa chaîne moto ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Oui, moteur coupé et moto stable, sans approcher les doigts du pignon ou de la couronne. Mesure le débattement selon la méthode et la valeur de ton constructeur. Points durs, maillons fissurés ou dents très usées : fais contrôler la transmission avant de rouler.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">À quoi sert le repère TWI sur un pneu moto ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Le repère TWI indique où se trouvent les témoins d’usure dans les rainures. Si la gomme atteint leur niveau, le pneu doit être remplacé. Une coupure, une hernie ou une usure anormale peut aussi imposer un contrôle ou un remplacement avant ce stade.</p><p class=\"lm-faq-source\"><a href=\"https://www.michelin.fr/motorbike/conseils-moto/regles-pneus/profondeur-de-sculpture-des-pneus-moto\" target=\"_blank\" rel=\"noopener noreferrer external\">Comprendre les témoins d’usure avec Michelin ↗</a></p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Peut-on inspecter les plaquettes et les disques sans démontage ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Souvent, un premier contrôle visuel est possible à travers l’étrier. Regarde la garniture des deux plaquettes et cherche des rayures profondes ou des fissures sur le disque. Les limites d’épaisseur dépendent de la moto : si tu vois mal ou si tu as un doute, passe par un professionnel.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Pourquoi le niveau du liquide de frein baisse-t-il ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Quand les plaquettes s’usent, les pistons avancent et le niveau du réservoir peut baisser sans qu’il y ait de fuite. Mais une baisse rapide, une trace de liquide ou un levier spongieux exigent un contrôle. N’ajoute pas de liquide au hasard.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Une huile moteur noire est-elle forcément à remplacer ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Non. La couleur seule ne suffit pas à juger l’huile. Respecte la méthode de lecture du niveau et les intervalles de vidange de ta notice. Une émulsion persistante, des particules inhabituelles, une baisse rapide ou un voyant de pression nécessitent un contrôle.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Comment contrôler le liquide de refroidissement sans danger ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Si ta moto possède un vase d’expansion, vérifie ses repères à froid, dans la position prescrite par le constructeur. N’ouvre jamais le bouchon d’un circuit chaud ou sous pression. Si le niveau baisse régulièrement ou si le moteur surchauffe, fais rechercher la cause.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Quels signes indiquent une batterie moto à surveiller ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Démarreur lent, clic au démarrage ou éclairage qui faiblit peuvent signaler un manque de charge, sans prouver à eux seuls que la batterie est morte. Vérifie aussi l’état visible des cosses et du boîtier. Une batterie gonflée, fissurée ou qui fuit ne doit pas être mise en charge.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Quels défauts imposent de faire contrôler la moto avant de rouler ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Un freinage anormal, une fuite suspecte, un pneu coupé ou déformé, une chaîne endommagée, une fuite importante à la fourche ou un voyant critique sont des signaux d’alerte. En cas de doute sur la sécurité, laisse la moto à l’arrêt et demande l’avis d’un professionnel.</p></div></details></div></section></div></div><div class=\"lm-desktop-content\"><div class=\"lm-desktop-reference\"><section aria-label=\"Sommaire interactif des contrôles\" class=\"lm-sommaire\">\n<div class=\"lm-hero-two-columns\"><nav aria-label=\"Sommaire des contrôles\" class=\"lm-hero-toc\"><h2>Au sommaire :</h2><a href=\"#controle-01\">Kit chaîne : tension, usure et graissage</a><a href=\"#controle-02\">Pneus : pression et état d’usure</a><a href=\"#controle-03\">Freins : plaquettes, disques et usure</a><a href=\"#controle-04\">Faire les niveaux : huile et liquides</a><a href=\"#controle-05\">Batterie : état et signes de faiblesse</a><a href=\"#controle-06\">Fourche : état des tubes et joints spi</a><a href=\"#controle-07\">Avant de partir : les 4 dernières vérifications rapides</a></nav><div class=\"lm-hero-visual\">\n<img alt=\"Moto roadster noire sans marque, sommaire interactif des contrôles\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5.webp\"/>\n<svg aria-hidden=\"true\" class=\"lm-map-connectors\" preserveaspectratio=\"none\" viewbox=\"0 0 100 100\"><polyline points=\"12,12 18,22 34,37\"></polyline><circle cx=\"34\" cy=\"37\" r=\"0.85\"></circle><polyline points=\"88,12 80,28 69,55\"></polyline><circle cx=\"69\" cy=\"55\" r=\"0.85\"></circle><polyline points=\"13,55 29,57 48,64\"></polyline><circle cx=\"48\" cy=\"64\" r=\"0.85\"></circle><polyline points=\"17,87 22,79 29,72\"></polyline><circle cx=\"29\" cy=\"72\" r=\"0.85\"></circle><polyline points=\"50,87 64,70 72,70\"></polyline><circle cx=\"72\" cy=\"70\" r=\"0.85\"></circle><polyline points=\"50,87 36,76 24,73\"></polyline><circle cx=\"24\" cy=\"73\" r=\"0.85\"></circle><polyline points=\"83,87 80,78\"></polyline><circle cx=\"80\" cy=\"78\" r=\"0.85\"></circle></svg><a aria-label=\"Aller à la rubrique 05 : Batterie\" class=\"lm-perimeter-btn lm-top-left\" href=\"#controle-05\" style=\"left:12%;top:8%\">Batterie</a><a aria-label=\"Aller à la rubrique 07 : Avant de partir\" class=\"lm-perimeter-btn lm-top-mid\" href=\"#controle-07\" style=\"left:50%;top:8%\">Avant de partir</a><a aria-label=\"Aller à la rubrique 06 : Fourche\" class=\"lm-perimeter-btn lm-top-right\" href=\"#controle-06\" style=\"left:88%;top:8%\">Fourche</a><a aria-label=\"Aller à la rubrique 04 : Niveaux\" class=\"lm-perimeter-btn lm-mid-left\" href=\"#controle-04\" style=\"left:13%;top:55%\">Niveaux</a><a aria-label=\"Aller à la rubrique 01 : Kit chaîne\" class=\"lm-perimeter-btn lm-bottom-left\" href=\"#controle-01\" style=\"left:17%;top:91%\">Kit chaîne</a><a aria-label=\"Aller à la rubrique 03 : Freins\" class=\"lm-perimeter-btn lm-bottom-mid\" href=\"#controle-03\" style=\"left:50%;top:91%\">Freins</a><a aria-label=\"Aller à la rubrique 02 : Pneus\" class=\"lm-perimeter-btn lm-bottom-right\" href=\"#controle-02\" style=\"left:83%;top:91%\">Pneus</a></div></div></section></div><div class=\"intro\"><h2>Comment vérifier sa moto soi-même en toute sécurité ?</h2><p>Installe la moto sur un sol stable, coupe le moteur et laisse refroidir les pièces chaudes. Garde tes doigts loin de la chaîne, protège pneus et freins des produits d’entretien et utilise la notice de ta moto pour les valeurs exactes.</p><div class=\"alert\"><strong>À savoir :</strong> ces vérifications visuelles ne remplacent ni les opérations d’entretien prévues par le constructeur ni un diagnostic professionnel.</div></div><details class=\"section\" id=\"controle-01\" open=\"\"><summary><span class=\"num\">01</span><span><h2>Kit chaîne : tension, usure et graissage</h2><span class=\"sub\">Inspecter, nettoyer et lubrifier la transmission</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Kit chaîne — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7c665d4329f05cc7-desktop-square.webp\"/><button aria-controls=\"p01-0\" aria-label=\"Ouvrir : État de la chaîne\" class=\"hotspot\" onclick=\"showPopup('p01-0')\" style=\"--x:19%;--y:39%\">1</button><div aria-label=\"État de la chaîne\" class=\"popup\" id=\"p01-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-0')\">×</button><img alt=\"Illustration : État de la chaîne\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-9598ba108629b2a6.webp\"/><div class=\"content\"><h3>Comment reconnaître une chaîne moto usée ?</h3><p>Cherche la corrosion, les points durs et les maillons abîmés. Une chaîne qui accroche ou présente des points durs persistants doit être examinée.</p></div></div><button aria-controls=\"p01-1\" aria-label=\"Ouvrir : Tension et débattement\" class=\"hotspot\" onclick=\"showPopup('p01-1')\" style=\"--x:52%;--y:41%\">2</button><div aria-label=\"Tension et débattement\" class=\"popup\" id=\"p01-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-1')\">×</button><img alt=\"Illustration : Tension et débattement\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-d19eb30c989c5787.webp\"/><div class=\"content\"><h3>Comment vérifier la tension de chaîne moto ?</h3><p>Vérifie le débattement au point indiqué par le constructeur. Fais tourner la roue à la main, moteur coupé, pour rechercher le point le plus tendu.</p></div></div><button aria-controls=\"p01-2\" aria-label=\"Ouvrir : Nettoyage et lubrification\" class=\"hotspot\" onclick=\"showPopup('p01-2')\" style=\"--x:36%;--y:67%\">3</button><div aria-label=\"Nettoyage et lubrification\" class=\"popup\" id=\"p01-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-2')\">×</button><img alt=\"Illustration : Nettoyage et lubrification\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-17feab5c52ca26b0.webp\"/><div class=\"content\"><h3>Comment nettoyer et graisser une chaîne moto ?</h3><p>Utilise un produit compatible et protège le pneu et les freins des projections. N’approche jamais les doigts d’une transmission en mouvement.</p></div></div><button aria-controls=\"p01-3\" aria-label=\"Ouvrir : Couronne et pignon\" class=\"hotspot\" onclick=\"showPopup('p01-3')\" style=\"--x:62%;--y:73%\">4</button><div aria-label=\"Couronne et pignon\" class=\"popup\" id=\"p01-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p01-3')\">×</button><img alt=\"Illustration : Couronne et pignon\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-adfb2bdc7802bdb9.webp\"/><div class=\"content\"><h3>Comment repérer l’usure du pignon et de la couronne ?</h3><p>Repère les dents anormalement pointues, crochues ou endommagées. Fais vérifier le kit complet si l’usure est marquée.</p></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Sur une moto stable, moteur coupé, observe les maillons, la tension et les dents. La valeur de jeu et la méthode de mesure dépendent du modèle : consulte la notice.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Sur une moto stable, moteur coupé, observe les maillons, la tension et les dents. La valeur de jeu et la méthode de mesure dépendent du modèle : consulte la notice.</p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(1,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-1\">1 / 5</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(1,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-1\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 5\" class=\"technical-card\"><h4>Repère les signes d’usure</h4><p>Inspecte les maillons, les joints et les dents de la couronne. Une plaque fissurée, un maillon grippé ou des dents très crochues signalent une usure anormale. Une chaîne fissurée impose l’immobilisation.</p></article><article aria-label=\"Conseil 2 sur 5\" class=\"technical-card\"><h4>Vérifie la tension</h4><p>Une chaîne trop tendue sollicite la transmission ; trop lâche, elle peut battre ou dérailler. Mesure sa flèche selon la méthode et la valeur indiquées par le constructeur.</p></article><article aria-label=\"Conseil 3 sur 5\" class=\"technical-card\"><h4>Nettoie sans abîmer les joints</h4><p>Utilise un nettoyant compatible avec les chaînes à joints et une brosse adaptée. Moteur coupé : ne fais jamais tourner la roue au moteur pour nettoyer la chaîne. Protège pneus et freins.</p></article><article aria-label=\"Conseil 4 sur 5\" class=\"technical-card\"><h4>Lubrifie correctement</h4><p>Sur une chaîne nécessitant une lubrification, applique un produit adapté sur la face intérieure, sans excès. Respecte son temps d’adhérence avant de rouler.</p></article><article aria-label=\"Conseil 5 sur 5\" class=\"technical-card\"><h4>Quand remplacer le kit ?</h4><p>Points durs persistants, allongement excessif ou dents très usées ? Fais contrôler chaîne, pignon et couronne ensemble. Un nettoyage ne répare pas une transmission en fin de vie.</p></article></div></details></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Illustration : État de la chaîne\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-9598ba108629b2a6-desktop-square.webp\"/><div class=\"content\"><h3>Comment reconnaître une chaîne moto usée ?</h3><p>Cherche la corrosion, les points durs et les maillons abîmés. Une chaîne qui accroche ou présente des points durs persistants doit être examinée.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Illustration : Tension et débattement\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-d19eb30c989c5787-desktop-square.webp\"/><div class=\"content\"><h3>Comment vérifier la tension de chaîne moto ?</h3><p>Vérifie le débattement au point indiqué par le constructeur. Fais tourner la roue à la main, moteur coupé, pour rechercher le point le plus tendu.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Illustration : Nettoyage et lubrification\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-17feab5c52ca26b0-desktop-square.webp\"/><div class=\"content\"><h3>Comment nettoyer et graisser une chaîne moto ?</h3><p>Utilise un produit compatible et protège le pneu et les freins des projections. N’approche jamais les doigts d’une transmission en mouvement.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Illustration : Couronne et pignon\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-adfb2bdc7802bdb9-desktop-square.webp\"/><div class=\"content\"><h3>Comment repérer l’usure du pignon et de la couronne ?</h3><p>Repère les dents anormalement pointues, crochues ou endommagées. Fais vérifier le kit complet si l’usure est marquée.</p></div></article><article class=\"lm-desktop-illustrated-card lm-original-card\"><img alt=\"Nettoyer la chaîne à la brosse\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/01-chaine-nettoyage.webp\"/><div class=\"content\"><h3>Nettoyer la chaîne à la brosse</h3><p>Utilise une brosse adaptée et un nettoyant compatible avec les joints. Moteur coupé, garde les doigts loin des zones de pincement.</p></div></article><article class=\"lm-desktop-illustrated-card lm-original-card\"><img alt=\"Repérer un point dur sur la chaîne\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/01-chaine-points-durs.webp\"/><div class=\"content\"><h3>Repérer un point dur sur la chaîne</h3><p>À l’arrêt, vérifie si certaines articulations restent raides lorsque tu fais tourner la roue à la main. Un point dur persistant doit être contrôlé.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><div class=\"accessory-nav lm-accessory-nav-more\"><button aria-label=\"Accessoire précédent\" data-direction=\"-1\" type=\"button\">‹</button><button aria-label=\"Accessoire suivant\" data-direction=\"1\" type=\"button\">›</button></div><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-1\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/brosse-chaine.png\" alt=\"Brosse pour chaîne — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Brosse souple pour chaîne</strong><span>Pour retirer les saletés sans agresser les joints.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/2447-moto-2024-brosse-chaine-tete-3-faces-3352341721241.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Brosse 3 faces</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/brosse-de-chaine\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · Brosse de chaîne</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/nettoyant-chaine.png\" alt=\"Nettoyant pour chaîne — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Nettoyant compatible chaînes à joints</strong><span>Évite les solvants inadaptés.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motul.com/en-FR/products/23001\" target=\"_blank\" rel=\"noopener noreferrer external\">Motul · MC Care C1</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/chain-cleaner\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · Chain Cleaner</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lubrifiant-chaine.png\" alt=\"Lubrifiant pour chaîne — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lubrifiant pour chaîne moto</strong><span>Choisis un produit compatible avec ta transmission.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motul.com/fr-FR/products/23301?product=MOTUL+MC+CARE+C2+CHAIN+LUBE+ROAD\" target=\"_blank\" rel=\"noopener noreferrer external\">Motul · MC Care C2 Road</a><a class=\"lm-fabricant-link\" href=\"https://www.ipone.com/fr/eshop/produit/x-trem-chain-road\" target=\"_blank\" rel=\"noopener noreferrer external\">IPONE · X-Trem Chain Road</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/mesure-chaine.png\" alt=\"Règle de mesure — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Règle graduée</strong><span>Pour mesurer le débattement selon la notice.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.motionpro.com/product/08-0674\" target=\"_blank\" rel=\"noopener noreferrer external\">Motion Pro · SlackSetter Pro</a><a class=\"lm-fabricant-link\" href=\"https://www.beta-tools.com/en/products/measuring-and-marking-tools/measuring-tapes-and-folding-rules/measuring-tapes-shock-resistant-bi-material-abs-casings-steel-tapes-precision-class-ii.html\" target=\"_blank\" rel=\"noopener noreferrer external\">BETA · Mètre 1692</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/bequille-arriere.png\" alt=\"Béquille arrière — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Béquille centrale ou d’atelier adaptée</strong><span>Seulement si la moto et la méthode de contrôle le permettent.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://lightech.it/en/yamaha_r9_2026/modular-iron-rear-stand-with-rollers-and-4-wheels.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Lightech · RSF039R (vérifier adaptation)</a><a class=\"lm-fabricant-link\" href=\"https://www.oxfordproducts.com/oxford-premium-rear-paddock-stand-ox281.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Oxford · Premium Rear OX281 (vérifier adaptation)</a></div></div></li></ul></details></div></details><details class=\"section\" id=\"controle-02\" open=\"\"><summary><span class=\"num\">02</span><span><h2>Pneus : pression et état d’usure</h2><span class=\"sub\">Usure, dommages, marquages et pression</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Pneus — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-b5a7faa1faad60b6-desktop-square.webp\"/><button aria-controls=\"p02-0\" aria-label=\"Ouvrir : Dommages visibles\" class=\"hotspot\" onclick=\"showPopup('p02-0')\" style=\"--x:70%;--y:24%\">1</button><div aria-label=\"Dommages visibles\" class=\"popup\" id=\"p02-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-0')\">×</button><img alt=\"Dommages : coupure, hernie, craquelures\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-1e8f1a81ce46d380.webp\"/><div class=\"content\"><h3>Pneu moto abîmé : coupures, hernies et craquelures</h3><p>Coupure, hernie ou craquelures importantes : évite de rouler et fais contrôler ou remplacer le pneu.</p></div></div><button aria-controls=\"p02-1\" aria-label=\"Ouvrir : Usure anormale\" class=\"hotspot\" onclick=\"showPopup('p02-1')\" style=\"--x:72%;--y:48%\">2</button><div aria-label=\"Usure anormale\" class=\"popup\" id=\"p02-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-1')\">×</button><img alt=\"Usures anormales : centre, épaules et facettes\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-5392edd72f2006ca.webp\"/><div class=\"content\"><h3>Usure irrégulière d’un pneu moto : les signes à repérer</h3><p>Contrôle le témoin d’usure et les différences entre centre, épaules et facettes. Une usure irrégulière mérite un diagnostic.</p></div></div><button aria-controls=\"p02-2\" aria-label=\"Ouvrir : Lire le marquage\" class=\"hotspot\" onclick=\"showPopup('p02-2')\" style=\"--x:43%;--y:44%\">3</button><div aria-label=\"Lire le marquage\" class=\"popup\" id=\"p02-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-2')\">×</button><img alt=\"Marquage du pneu : 120/70 R17 58W\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-7fdbe8c96b5b2fe9.webp\"/><div class=\"content\"><h3>Comment lire les dimensions et indices d’un pneu moto ?</h3><p>Exemple : 120/70 R17 58W. Vérifie les dimensions et les indices homologués pour ta moto.</p></div></div><button aria-controls=\"p02-3\" aria-label=\"Ouvrir : Pression\" class=\"hotspot\" onclick=\"showPopup('p02-3')\" style=\"--x:39%;--y:76%\">4</button><div aria-label=\"Pression\" class=\"popup\" id=\"p02-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-3')\">×</button><img alt=\"Pression à froid : valve et manomètre\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-1780908908502bcd.webp\"/><div class=\"content\"><h3>Comment contrôler la pression des pneus moto à froid ?</h3><p>Mesure à froid avec un manomètre. La valeur affichée est illustrative : utilise la pression prescrite par le constructeur, selon la charge.</p></div></div><button aria-controls=\"p02-4\" aria-label=\"Ouvrir : date de fabrication DOT\" class=\"hotspot\" onclick=\"showPopup('p02-4')\" style=\"--x:17%;--y:64%\">5</button><div aria-label=\"Date de fabrication DOT\" class=\"popup dot-popup\" id=\"p02-4\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p02-4')\">×</button><div class=\"dot-inner\"><img alt=\"Marquage photographié 4020 sur le flanc d’un pneu\" class=\"dot-photo\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-59d72c0f052f2669.webp\"/><div class=\"dot-copy\"><h3>DOT pneu moto : comment lire la date de fabrication ?</h3><div class=\"dot-values\"><div><strong>40</strong><span>40ᵉ semaine</span></div><div><strong>20</strong><span>Année 2020</span></div></div><p><strong>4020</strong> signifie que ce pneu a été fabriqué durant la 40ᵉ semaine de 2020.</p><p>Lors d’un achat d’occasion, vérifie le code de date sur les deux pneus, leur état et les éventuelles craquelures. La date seule ne fixe pas une péremption.</p></div></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Regarde toute la bande de roulement et les flancs, puis contrôle la pression à froid. Le marquage illustré est un exemple : il ne remplace pas les spécifications de ta moto.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Regarde toute la bande de roulement et les flancs, puis contrôle la pression à froid. Le marquage illustré est un exemple : il ne remplace pas les spécifications de ta moto.</p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(2,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-2\">1 / 5</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(2,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-2\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 5\" class=\"technical-card\"><h4>Contrôle la pression à froid</h4><p>Un pneu peut sembler bien gonflé alors qu’il manque de pression. Utilise un manomètre et les valeurs de ta moto adaptées à la charge, pas la pression maximale inscrite sur le pneu.</p></article><article aria-label=\"Conseil 2 sur 5\" class=\"technical-card\"><h4>Mesure l’usure</h4><p>Repère les témoins TWI et mesure la profondeur des rainures avec une jauge. Vérifie aussi les exigences réglementaires applicables : le témoin seul ne remplace pas une mesure.</p></article><article aria-label=\"Conseil 3 sur 5\" class=\"technical-card\"><h4>Inspecte flancs et bande de roulement</h4><p>Cherche hernies, fissures profondes, coupures ou objets plantés. Une hernie ou une carcasse visible impose de ne pas rouler. Ne retire pas un objet incrusté sans évaluation.</p></article><article aria-label=\"Conseil 4 sur 5\" class=\"technical-card\"><h4>Reconnais l’usure irrégulière</h4><p>Un pneu aplati au centre peut modifier le comportement de la moto. Une usure anormale peut aussi révéler un souci de pression, de charge ou de suspension.</p></article><article aria-label=\"Conseil 5 sur 5\" class=\"technical-card\"><h4>Comprends la date DOT</h4><p>Les quatre chiffres du code de date indiquent la semaine et l’année de fabrication. L’âge seul ne suffit pas : état, stockage et recommandations du fabricant comptent aussi.</p></article></div></details></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Dommages : coupure, hernie, craquelures\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1e8f1a81ce46d380-desktop-square.webp\"/><div class=\"content\"><h3>Pneu moto abîmé : coupures, hernies et craquelures</h3><p>Coupure, hernie ou craquelures importantes : évite de rouler et fais contrôler ou remplacer le pneu.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Usures anormales : centre, épaules et facettes\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-5392edd72f2006ca-desktop-square.webp\"/><div class=\"content\"><h3>Usure irrégulière d’un pneu moto : les signes à repérer</h3><p>Contrôle le témoin d’usure et les différences entre centre, épaules et facettes. Une usure irrégulière mérite un diagnostic.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Marquage du pneu : 120/70 R17 58W\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7fdbe8c96b5b2fe9-desktop-square.webp\"/><div class=\"content\"><h3>Comment lire les dimensions et indices d’un pneu moto ?</h3><p>Exemple : 120/70 R17 58W. Vérifie les dimensions et les indices homologués pour ta moto.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Pression à froid : valve et manomètre\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1780908908502bcd-desktop-square.webp\"/><div class=\"content\"><h3>Comment contrôler la pression des pneus moto à froid ?</h3><p>Mesure à froid avec un manomètre. La valeur affichée est illustrative : utilise la pression prescrite par le constructeur, selon la charge.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Marquage photographié 4020 sur le flanc d’un pneu\" class=\"dot-photo lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-59d72c0f052f2669-desktop-square.webp\"/><div class=\"content lm-dot-desktop-copy\"><h3>DOT pneu moto : comment lire la date de fabrication ?</h3><div class=\"dot-values\"><div><strong>40</strong><span>40ᵉ semaine</span></div><div><strong>20</strong><span>Année 2020</span></div></div><p><strong>4020</strong> signifie que ce pneu a été fabriqué durant la 40ᵉ semaine de 2020.</p><p>Lors d’un achat d’occasion, vérifie le code de date sur les deux pneus, leur état et les éventuelles craquelures. La date seule ne fixe pas une péremption.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-2\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/manometre.png\" alt=\"Manomètre — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Manomètre fiable</strong><span>Pour contrôler la pression à froid.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.oxfordproducts.com/oxford-tyre-gauge-pro-dial-type-0-60psi-ox750.html\" target=\"_blank\" rel=\"noopener noreferrer external\">Oxford · Tyre Gauge Pro OX750</a><a class=\"lm-fabricant-link\" href=\"https://slime.com/products/digital-tire-gauge-5-150-psi\" target=\"_blank\" rel=\"noopener noreferrer external\">Slime · Digital Tire Gauge 20017</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/jauge-pneus.png\" alt=\"Jauge de profondeur — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Jauge de profondeur de sculpture</strong><span>Pour mesurer les rainures, pas seulement regarder les témoins.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.clas.com/fr/jauge-de-profondeur-pour-pneus-ac-4951.html\" target=\"_blank\" rel=\"noopener noreferrer external\">CLAS · AC4951</a><a class=\"lm-fabricant-link\" href=\"https://www.lasertools.co.uk/pis/4262_PIS.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Laser Tools · Jauge numérique 4262</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe d’inspection</strong><span>Pour examiner flancs, entailles et craquelures.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon microfibre — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Chiffon doux</strong><span>Pour nettoyer une zone de marquage sans l’abîmer.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details></div></details><details class=\"section\" id=\"controle-03\" open=\"\"><summary><span class=\"num\">03</span><span><h2>Freins : plaquettes, disques et usure</h2><span class=\"sub\">Plaquettes, disques et signes d’alerte</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Freins — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-8630811240c2e647-desktop-square.webp\"/><button aria-label=\"État du disque\" class=\"hotspot\" onclick=\"showPopup('p03-1')\" style=\"--x:58%;--y:76%\" type=\"button\">2</button><button aria-label=\"Plaquettes de frein\" class=\"hotspot\" onclick=\"showPopup('p03-0')\" style=\"--x:35%;--y:50%\" type=\"button\">1</button><button aria-label=\"Observer sans démontage\" class=\"hotspot\" onclick=\"showPopup('p03-3')\" style=\"--x:65%;--y:35%\" type=\"button\">4</button><button aria-label=\"Plaquette neuve et usée\" class=\"hotspot\" onclick=\"showPopup('p03-2')\" style=\"--x:33%;--y:67%\" type=\"button\">3</button><div aria-label=\"Épaisseur des plaquettes\" class=\"popup\" id=\"p03-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-0')\">×</button><img alt=\"Gros plan sur la garniture et les témoins d’usure, sans roue en arrière-plan\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-4dc2934722736ed2.webp\"/><div class=\"content\"><h3>Comment vérifier l’usure des plaquettes de frein moto ?</h3><p>Repère la garniture et le témoin d’usure, lorsqu’il est visible. Si la garniture est très mince ou si tu as un doute, fais vérifier les freins.</p></div></div><div aria-label=\"État des disques\" class=\"popup\" id=\"p03-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-1')\">×</button><img alt=\"Illustration : État des disques\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-ea4ab82b988441f4.webp\"/><div class=\"content\"><h3>Disque de frein moto : repérer les signes d’usure</h3><p>Recherche rayures profondes, fissures, voile ou changement anormal d’aspect. La limite d’épaisseur est propre au disque.</p></div></div><div aria-label=\"Plaquette neuve et usée\" class=\"popup\" id=\"p03-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-2')\">×</button><img alt=\"Plaquette neuve et usée\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-980819ef458a6c1b.webp\"/><div class=\"content\"><h3>Plaquette de frein moto neuve ou usée : comparer la garniture</h3><p>Compare l’épaisseur de la garniture de friction (zone orange), sans la confondre avec le support métallique. Respecte la limite indiquée par le constructeur.</p></div></div><div aria-label=\"Observer sans démontage\" class=\"popup\" id=\"p03-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p03-3')\">×</button><img alt=\"Observer sans démontage\" loading=\"eager\" src=\"/images/entretien-moto-guide/controle-50d01a587d721610.webp\"/><div class=\"content\"><h3>Comment voir les plaquettes de frein sans démontage ?</h3><p>Regarde par l’ouverture de l’étrier pour repérer la garniture entre le support métallique et le disque. Selon le modèle, l’accès peut être limité : fais vérifier les deux plaquettes si tu ne peux pas les voir correctement.</p></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Un freinage spongieux, un bruit inhabituel, des vibrations ou une fuite sont des raisons de faire contrôler rapidement le système. Ne démonte pas les freins sans compétence adaptée.</p><p><strong>Faire contrôler l’usure des freins :</strong> si tu ne parviens pas à voir l’épaisseur de la garniture ou si le disque présente des rainures, fais contrôler tes freins par un professionnel. Il pourra mesurer l’épaisseur des plaquettes et du disque, puis comparer les résultats aux limites indiquées par le constructeur.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Un freinage spongieux, un bruit inhabituel, des vibrations ou une fuite sont des raisons de faire contrôler rapidement le système. Ne démonte pas les freins sans compétence adaptée.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/map\">Faire contrôler tes freins par un professionnel ↗</a></p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(3,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-3\">1 / 10</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(3,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-3\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 10\" class=\"technical-card\"><h4>Identifie la garniture</h4><p>Une plaquette comprend un support métallique et une garniture de friction. C’est la garniture qui s’use : ne confonds pas son épaisseur avec celle de la plaquette entière.</p></article><article aria-label=\"Conseil 2 sur 10\" class=\"technical-card\"><h4>Observe les deux plaquettes</h4><p>Vérifie les faces intérieure et extérieure du disque : elles peuvent s’user différemment. La limite d’épaisseur dépend du fabricant.</p></article><article aria-label=\"Conseil 3 sur 10\" class=\"technical-card\"><h4>Inspecte le disque</h4><p>De fines traces circulaires peuvent être normales. Fissures, rainures profondes ou usure importante nécessitent un contrôle. MIN TH indique l’épaisseur minimale lorsqu’elle est marquée.</p></article><article aria-label=\"Conseil 4 sur 10\" class=\"technical-card\"><h4>Reconnais un freinage anormal</h4><p>Levier soudainement mou, course excessive, vibrations inhabituelles ou bruit métallique persistant : plusieurs causes sont possibles. Perte d’efficacité ou fuite : ne roule pas.</p></article><article aria-label=\"Conseil 5 sur 10\" class=\"technical-card\"><h4>Quand consulter ?</h4><p>Si les plaquettes approchent leur limite ou si le disque semble endommagé, fais vérifier le système. L’inspection visuelle est accessible ; la réparation exige des compétences adaptées.</p></article><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4>Repère les réservoirs</h4><p>Celui du frein avant se trouve souvent près du levier droit ; celui de l’arrière près du cadre. Ils peuvent posséder un hublot ou une paroi translucide.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4>Lis le niveau sans ouvrir</h4><p>Sur une moto droite et selon la position indiquée dans la notice, regarde si le liquide se situe entre les repères MIN et MAX. Un niveau bas peut être lié à l’usure des plaquettes, mais aussi à une fuite : fais contrôler si tu as un doute. N’ouvre pas le bocal pour une simple vérification.</p></article><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4>Comprends la baisse du niveau</h4><p>Quand les plaquettes s’usent, les pistons avancent. Le liquide descend alors dans le réservoir : ce n’est pas forcément une fuite. Évite tout appoint au hasard.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4>Couleur et type de liquide</h4><p>La couleur ne mesure pas la teneur en eau. Respecte les intervalles constructeur. DOT 3, 4 et 5.1 sont glycolés ; DOT 5 est à base de silicone et ne doit pas être confondu avec DOT 5.1.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4>Reconnais une anomalie</h4><p>Levier spongieux, course inhabituelle, fuite ou baisse rapide du niveau : fais contrôler le circuit. En cas de défaut de freinage, ne roule pas. N’ouvre pas le réservoir pour une simple inspection.</p></article></div></details></div><div class=\"lm-desktop-advice-flow\" aria-label=\"Conseils pratiques\" data-lm-continued-typography=\"20261114\"><div class=\"lm-continuation-grid\"><div class=\"lm-continuation-column\"><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Repère les réservoirs</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Celui du frein avant se trouve souvent près du levier droit ; celui de l’arrière près du cadre. Ils peuvent posséder un hublot ou une paroi translucide.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Lis le niveau sans ouvrir</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Sur une moto droite et selon la position indiquée dans la notice, regarde si le liquide se situe entre les repères MIN et MAX. Un niveau bas peut être lié à l’usure des plaquettes, mais aussi à une fuite : fais contrôler si tu as un doute. N’ouvre pas le bocal pour une simple vérification.</p></article></div><div class=\"lm-continuation-column\"><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Comprends la baisse du niveau</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Quand les plaquettes s’usent, les pistons avancent. Le liquide descend alors dans le réservoir : ce n’est pas forcément une fuite. Évite tout appoint au hasard.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Couleur et type de liquide</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">La couleur ne mesure pas la teneur en eau. Respecte les intervalles constructeur. DOT 3, 4 et 5.1 sont glycolés ; DOT 5 est à base de silicone et ne doit pas être confondu avec DOT 5.1.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Reconnais une anomalie</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Levier spongieux, course inhabituelle, fuite ou baisse rapide du niveau : fais contrôler le circuit. En cas de défaut de freinage, ne roule pas. N’ouvre pas le réservoir pour une simple inspection.</p></article></div></div></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Gros plan sur la garniture et les témoins d’usure, sans roue en arrière-plan\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-4dc2934722736ed2-desktop-square.webp\"/><div class=\"content\"><h3>Comment vérifier l’usure des plaquettes de frein moto ?</h3><p>Repère la garniture et le témoin d’usure, lorsqu’il est visible. Si la garniture est très mince ou si tu as un doute, fais vérifier les freins.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Illustration : État des disques\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-ea4ab82b988441f4-desktop-square.webp\"/><div class=\"content\"><h3>Disque de frein moto : repérer les signes d’usure</h3><p>Recherche rayures profondes, fissures, voile ou changement anormal d’aspect. La limite d’épaisseur est propre au disque.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Plaquette neuve et usée\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-980819ef458a6c1b-desktop-square.webp\"/><div class=\"content\"><h3>Plaquette de frein moto neuve ou usée : comparer la garniture</h3><p>Compare l’épaisseur de la garniture de friction (zone orange), sans la confondre avec le support métallique. Respecte la limite indiquée par le constructeur.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Observer sans démontage\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-50d01a587d721610-desktop-square.webp\"/><div class=\"content\"><h3>Comment voir les plaquettes de frein sans démontage ?</h3><p>Regarde par l’ouverture de l’étrier pour repérer la garniture entre le support métallique et le disque. Selon le modèle, l’accès peut être limité : fais vérifier les deux plaquettes si tu ne peux pas les voir correctement.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-3\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe d’inspection</strong><span>Pour observer l’épaisseur des garnitures et les disques.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon microfibre — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Chiffon propre</strong><span>Pour nettoyer les surfaces extérieures accessibles, sans contaminer les freins.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details></div></details><details class=\"section\" id=\"controle-04\" open=\"\"><summary><span class=\"num\">04</span><span><h2>Faire les niveaux : huile et liquides</h2><span class=\"sub\">Huile moteur, liquide de frein, liquide de refroidissement et contrôle de l’embrayage</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Moto roadster noire sans marque sur fond neutre, points de contrôle interactifs\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5-desktop-square.webp\"/><button aria-controls=\"p04-0\" aria-label=\"Ouvrir : Embrayage\" class=\"hotspot\" onclick=\"showPopup('p04-0')\" style=\"--x:80%;--y:29.8%\">1</button><div aria-label=\"Embrayage\" class=\"popup\" id=\"p04-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-0')\">×</button><img alt=\"Embrayage\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-28ce7aa24d44125c.webp\"/><div class=\"content\"><h3>Embrayage moto : câble ou hydraulique, que vérifier ?</h3><p>Selon la moto, l’embrayage fonctionne par câble ou par circuit hydraulique. Un modèle à câble n’a pas de réservoir de liquide d’embrayage.</p></div></div><button aria-controls=\"p04-1\" aria-label=\"Ouvrir : Liquide de frein\" class=\"hotspot\" onclick=\"showPopup('p04-1')\" style=\"--x:55%;--y:29.8%\">2</button><div aria-label=\"Liquide de frein\" class=\"popup\" id=\"p04-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-1')\">×</button><img alt=\"Liquide de frein\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-57975ddafe14a7ac.webp\"/><div class=\"content\"><h3>Liquide de frein moto : où trouver les bocaux et lire le niveau ?</h3><p>Contrôle les repères MIN/MAX des réservoirs avant et arrière, moto dans la position prévue par la notice. Une baisse de niveau peut accompagner l’usure des plaquettes ou signaler une fuite.</p></div></div><button aria-controls=\"p04-2\" aria-label=\"Ouvrir : Liquide de refroidissement\" class=\"hotspot\" onclick=\"showPopup('p04-2')\" style=\"--x:66%;--y:59.8%\">3</button><div aria-label=\"Liquide de refroidissement\" class=\"popup\" id=\"p04-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-2')\">×</button><img alt=\"Liquide de refroidissement\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7c9c444dc2001731.webp\"/><div class=\"content\"><h3>Liquide de refroidissement moto : contrôler le niveau à froid</h3><p>Moteur froid, vérifie le vase d’expansion entre MIN et MAX selon la notice. N’ouvre jamais un bouchon de circuit sous pression à chaud.</p></div></div><button aria-controls=\"p04-3\" aria-label=\"Ouvrir : Huile moteur\" class=\"hotspot\" onclick=\"showPopup('p04-3')\" style=\"--x:43%;--y:59.0%\">4</button><div aria-label=\"Huile moteur\" class=\"popup\" id=\"p04-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p04-3')\">×</button><img alt=\"Huile moteur\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-cc1948992f27ba22.webp\"/><div class=\"content\"><h3>Niveau d’huile moto : comment lire le hublot ou la jauge ?</h3><p>Contrôle par hublot ou jauge selon la procédure du constructeur : moto droite ou sur béquille adaptée, moteur froid ou après attente prescrite.</p></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Quatre vérifications regroupées sur une seule moto. Les positions montrées sont indicatives : chaque modèle place ses réservoirs et ses repères différemment.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Quatre vérifications regroupées sur une seule moto. Les positions montrées sont indicatives : chaque modèle place ses réservoirs et ses repères différemment.</p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(4,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-4\">1 / 10</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(4,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-4\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 10\" class=\"technical-card\"><h4>Huile moteur : repère le niveau</h4><p>Repère le hublot ou la jauge et suis exactement la procédure de ta notice : position de la moto, température du moteur et délai d’attente peuvent varier selon le modèle.</p></article><article aria-label=\"Conseil 2 sur 10\" class=\"technical-card\"><h4>Huile : interprète et réagis</h4><p>Lis la plage indiquée et évite le surremplissage. Une couleur sombre seule ne prouve pas une huile usée ; émulsion persistante, particules métalliques, baisse rapide ou voyant de pression imposent un contrôle.</p></article><article aria-label=\"Conseil 3 sur 10\" class=\"technical-card\"><h4>Refroidissement : contrôle à froid</h4><p>Si ta moto possède un vase d’expansion, vérifie les repères MIN/MAX à froid, dans la position prévue. N’ouvre jamais le bouchon d’un circuit chaud ou sous pression.</p></article><article aria-label=\"Conseil 4 sur 10\" class=\"technical-card\"><h4>Refroidissement : repère les anomalies</h4><p>Surveille les fuites, dépôts secs, durites abîmées et baisses répétées. Respecte la spécification du liquide, pas seulement sa couleur. En cas de surchauffe, arrête-toi en sécurité.</p></article><article aria-label=\"Conseil 5 sur 10\" class=\"technical-card\"><h4>Freins : localise les réservoirs</h4><p>Le bocal de frein avant se trouve généralement au guidon, près du levier droit. Celui du frein arrière est souvent situé sous la selle, derrière un cache latéral ou à proximité de l’amortisseur arrière, parfois près du maître-cylindre et de la pédale de frein. Leur emplacement varie selon la moto : consulte la notice constructeur pour les localiser et lire les niveaux dans la position prescrite, sans ouvrir les réservoirs.</p></article><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4>Freins : comprends le niveau</h4><p>Un niveau qui baisse peut accompagner l’usure des plaquettes, sans être nécessairement une fuite. Contrôle l’état des plaquettes et recherche toute baisse anormale avant d’envisager un appoint.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4>Freins : liquide et signes d’alerte</h4><p>La couleur ne permet pas de juger l’humidité du liquide. Respecte le type et l’intervalle constructeur. Levier spongieux, fuite ou freinage anormal : ne roule pas et fais contrôler le circuit.</p></article><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4>Embrayage : câble ou hydraulique ?</h4><p>Identifie le système de ta moto : câble avec gaine, ou circuit hydraulique avec maître-cylindre. Les contrôles et les fluides éventuels ne sont pas interchangeables.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4>Embrayage : vérifie la commande</h4><p>Pour un câble, observe garde, gaine et brins effilochés selon la notice. Pour un circuit hydraulique, recherche les fuites et une modification de sensation au levier ; respecte le fluide prescrit.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4>Embrayage : reconnais un défaut</h4><p>Patinage à l’accélération, point mort difficile ou moto qui cherche à avancer levier serré peuvent révéler un défaut de commande ou d’embrayage : fais diagnostiquer si le phénomène persiste.</p></article></div></details></div><div class=\"lm-desktop-advice-flow\" aria-label=\"Conseils pratiques\" data-lm-continued-typography=\"20261114\"><div class=\"lm-continuation-grid\"><div class=\"lm-continuation-column\"><article aria-label=\"Conseil 5 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Freins : localise les réservoirs</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Le bocal de frein avant se trouve généralement au guidon, près du levier droit. Celui du frein arrière est souvent situé sous la selle, derrière un cache latéral ou à proximité de l’amortisseur arrière, parfois près du maître-cylindre et de la pédale de frein. Leur emplacement varie selon la moto : consulte la notice constructeur pour les localiser et lire les niveaux dans la position prescrite, sans ouvrir les réservoirs.</p></article><article aria-label=\"Conseil 6 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Freins : comprends le niveau</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Un niveau qui baisse peut accompagner l’usure des plaquettes, sans être nécessairement une fuite. Contrôle l’état des plaquettes et recherche toute baisse anormale avant d’envisager un appoint.</p></article><article aria-label=\"Conseil 7 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Freins : liquide et signes d’alerte</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">La couleur ne permet pas de juger l’humidité du liquide. Respecte le type et l’intervalle constructeur. Levier spongieux, fuite ou freinage anormal : ne roule pas et fais contrôler le circuit.</p></article></div><div class=\"lm-continuation-column\"><article aria-label=\"Conseil 8 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Embrayage : câble ou hydraulique ?</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Identifie le système de ta moto : câble avec gaine, ou circuit hydraulique avec maître-cylindre. Les contrôles et les fluides éventuels ne sont pas interchangeables.</p></article><article aria-label=\"Conseil 9 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Embrayage : vérifie la commande</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Pour un câble, observe garde, gaine et brins effilochés selon la notice. Pour un circuit hydraulique, recherche les fuites et une modification de sensation au levier ; respecte le fluide prescrit.</p></article><article aria-label=\"Conseil 10 sur 10\" class=\"technical-card\"><h4 style=\"font-size:16px!important;font-weight:750!important;line-height:1.4!important;margin:0 0 5px!important;color:#17202a!important\">Embrayage : reconnais un défaut</h4><p style=\"font-size:15px!important;line-height:1.6!important;margin:0!important\">Patinage à l’accélération, point mort difficile ou moto qui cherche à avancer levier serré peuvent révéler un défaut de commande ou d’embrayage : fais diagnostiquer si le phénomène persiste.</p></article></div></div></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Embrayage\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-28ce7aa24d44125c-desktop-square.webp\"/><div class=\"content\"><h3>Embrayage moto : câble ou hydraulique, que vérifier ?</h3><p>Selon la moto, l’embrayage fonctionne par câble ou par circuit hydraulique. Un modèle à câble n’a pas de réservoir de liquide d’embrayage.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Liquide de frein\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-57975ddafe14a7ac-desktop-square.webp\"/><div class=\"content\"><h3>Liquide de frein moto : où trouver les bocaux et lire le niveau ?</h3><p>Contrôle les repères MIN/MAX des réservoirs avant et arrière, moto dans la position prévue par la notice. Une baisse de niveau peut accompagner l’usure des plaquettes ou signaler une fuite.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Liquide de refroidissement\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7c9c444dc2001731-desktop-square.webp\"/><div class=\"content\"><h3>Liquide de refroidissement moto : contrôler le niveau à froid</h3><p>Moteur froid, vérifie le vase d’expansion entre MIN et MAX selon la notice. N’ouvre jamais un bouchon de circuit sous pression à chaud.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Huile moteur\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-cc1948992f27ba22-desktop-square.webp\"/><div class=\"content\"><h3>Niveau d’huile moto : comment lire le hublot ou la jauge ?</h3><p>Contrôle par hublot ou jauge selon la procédure du constructeur : moto droite ou sur béquille adaptée, moteur froid ou après attente prescrite.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-4\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe et chiffon propre</strong><span>Pour lire les repères de niveau.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/entonnoir.png\" alt=\"Entonnoir — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Entonnoir propre adapté</strong><span>Uniquement si un appoint est prévu par la notice.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.drapertools.com/product/56141/pvc-flexible-funnel/\" target=\"_blank\" rel=\"noopener noreferrer external\">Draper · 56141</a><a class=\"lm-fabricant-link\" href=\"https://www.pressol.com/resources/portalmedia/media/16745499_20190723_HST_GB.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Pressol · Entonnoir 02 662 (PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div aria-label=\"Emplacement pour la photo du produit\" class=\"lm-affiliate-image\">Photo du matériel à ajouter</div><strong>Liquides aux spécifications constructeur</strong><span>Ne mélange pas des produits non compatibles.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Référence à renseigner</span><span class=\"lm-affiliate-link-pending\">Lien affilié à ajouter</span></div></li></ul></details></div></details><details class=\"section\" id=\"controle-05\" open=\"\"><summary><span class=\"num\">05</span><span><h2>Batterie : état et signes de faiblesse</h2><span class=\"sub\">Oxydation, déformation et témoin éventuel</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Batterie — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/batterie-principale-desktop-desktop-square.webp\"/><button aria-controls=\"p05-location\" aria-label=\"Localiser la batterie\" class=\"hotspot\" onclick=\"showPopup('p05-location')\" style=\"--x:68%;--y:24%\" type=\"button\">1</button><div aria-label=\"Localiser la batterie\" class=\"popup\" id=\"p05-location\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p05-location')\">×</button><figure class=\"location-figure\" style=\"display:block!important;width:100%!important;max-width:100%!important;margin:0 0 9px!important;padding:0!important;\"><figcaption style=\"display:block;margin:0 0 6px;font-weight:700;color:#b84b00;\">Sous la selle</figcaption><img alt=\"Photographie originale : batterie située sous la selle\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7822f0eeb9123667.webp\" style=\"display:block!important;width:100%!important;max-width:100%!important;height:auto!important;max-height:none!important;object-fit:cover!important;margin:0!important;border-radius:10px;\"/></figure><figure class=\"location-figure\" style=\"display:block!important;width:100%!important;max-width:100%!important;margin:0 0 9px!important;padding:0!important;\"><figcaption style=\"display:block;margin:0 0 6px;font-weight:700;color:#b84b00;\">Derrière un cache latéral</figcaption><img alt=\"Photographie originale : batterie située derrière un cache latéral\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-6139ad2a6de45990.webp\" style=\"display:block!important;width:100%!important;max-width:100%!important;height:auto!important;max-height:none!important;object-fit:cover!important;margin:0!important;border-radius:10px;\"/></figure></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Inspecte visuellement la batterie et ses connexions, moteur coupé. Cherche les traces d’oxydation, un boîtier gonflé, des fuites ou des câbles abîmés. Le témoin visuel, lorsqu’il existe, ne suffit pas à diagnostiquer toutes les batteries.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Inspecte visuellement la batterie et ses connexions, moteur coupé. Cherche les traces d’oxydation, un boîtier gonflé, des fuites ou des câbles abîmés. Le témoin visuel, lorsqu’il existe, ne suffit pas à diagnostiquer toutes les batteries.</p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(5,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-5\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(5,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-5\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Reconnais une batterie faible</h4><p>Démarreur lent, clic au démarrage ou voyants qui faiblissent : la batterie peut manquer de charge. Un mauvais contact ou un défaut du démarreur peut produire les mêmes symptômes.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Observe son état extérieur</h4><p>Si elle est accessible sans intervention, recherche un boîtier gonflé ou fissuré, une fuite ou une corrosion importante. Une batterie endommagée ne doit pas être mise en charge.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Pourquoi se décharge-t-elle ?</h4><p>Trajets courts, immobilisation, vieillissement ou défaut de recharge : plusieurs causes existent. Un USB ou un accessoire alimenté en permanence peut aussi consommer du courant à l’arrêt.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Recharger ou remplacer ?</h4><p>Une batterie déchargée n’est pas forcément hors service. Un professionnel peut tester sa capacité et le circuit de charge. Pour l’hivernage, le maintien de charge doit être adapté à la batterie.</p></article></div></details></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Photographie originale : batterie située sous la selle\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-7822f0eeb9123667-desktop-square.webp\" style=\"display:block!important;width:100%!important;max-width:100%!important;height:auto!important;max-height:none!important;object-fit:cover!important;margin:0!important;border-radius:10px;\"/><div class=\"content\"><h3>Repérer la batterie sous la selle</h3><p>Inspecte visuellement la batterie et ses connexions, moteur coupé. Cherche les traces d’oxydation, un boîtier gonflé, des fuites ou des câbles abîmés.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Oxydation des bornes\" loading=\"lazy\" src=\"/images/entretien-moto-guide/batterie_oxydation-desktop-square.webp\"/><div class=\"content\"><h3>Oxydation des bornes</h3><p>Repère les traces de corrosion autour des connexions.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Déformation du boîtier\" loading=\"lazy\" src=\"/images/entretien-moto-guide/batterie_deformation-desktop-square.webp\"/><div class=\"content\"><h3>Déformation du boîtier</h3><p>Un boîtier gonflé ou fissuré impose un contrôle professionnel.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Témoin visuel\" loading=\"lazy\" src=\"/images/entretien-moto-guide/batterie_temoin-desktop-square.webp\"/><div class=\"content\"><h3>Témoin visuel</h3><p>Un témoin éventuel ne suffit pas à diagnostiquer la batterie.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-5\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe d’inspection</strong><span>Pour observer le boîtier et les connexions accessibles.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div aria-label=\"Emplacement pour la photo du produit\" class=\"lm-affiliate-image\">Photo du matériel à ajouter</div><strong>Chargeur de maintien compatible</strong><span>À choisir selon la technologie de la batterie.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Référence à renseigner</span><span class=\"lm-affiliate-link-pending\">Lien affilié à ajouter</span></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/gants-nitrile.png\" alt=\"Gants de protection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Gants et lunettes de protection</strong><span>Pour toute intervention autorisée par le fabricant.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Gants nitrile (lunettes à choisir séparément)</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.ansell.com/fr/fr/products/touchntuff-92-600\" target=\"_blank\" rel=\"noopener noreferrer external\">Ansell · TouchNTuff 92-600</a><a class=\"lm-fabricant-link\" href=\"https://www.showagroup.com/eu-en/shop/7500pf/\" target=\"_blank\" rel=\"noopener noreferrer external\">SHOWA · 7500PF</a></div></div></li></ul></details></div></details><details class=\"section\" id=\"controle-06\" open=\"\"><summary><span class=\"num\">06</span><span><h2>Fourche : état des tubes et joints spi</h2><span class=\"sub\">Comparer une fourche sèche et une fuite probable</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Fourche et joints spi — illustration de contrôle moto\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-62d964a9681690c5-desktop-square.webp\"/><button aria-controls=\"p06-0\" aria-label=\"Ouvrir : Tube piqué ou rayé\" class=\"hotspot\" onclick=\"showPopup('p06-0')\" style=\"--x:52%;--y:29%\">1</button><div aria-label=\"Tube piqué ou rayé\" class=\"popup\" id=\"p06-0\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p06-0')\">×</button><img alt=\"Tube piqué ou rayé\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-da04df55dc6a3957.webp\"/><div class=\"content\"><h3>Tube de fourche piqué ou rayé : quels signes surveiller ?</h3><p>Des piqûres, rayures ou traces de corrosion sur la zone de coulissement peuvent détériorer le joint spi. Fais contrôler la fourche si le chrome est endommagé.</p></div></div><button aria-label=\"Ouvrir : cache-poussière craquelé et trace grasse\" class=\"hotspot\" onclick=\"showPopup('p06-joint')\" style=\"--x:76%;--y:54%\" type=\"button\">2</button><div aria-label=\"Inspection du cache-poussière et du joint\" class=\"popup\" id=\"p06-joint\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p06-joint')\">×</button><img alt=\"Photographie originale : cache-poussière de fourche craquelé et traces grasses autour du joint\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-e83f8ef1c7816175.webp\"/><div class=\"content\"><h3>Joint spi et cache-poussière de fourche : craquelures et traces d’huile</h3><p>Observe les craquelures du caoutchouc, le dépôt noir et les traces grasses autour du tube. Ces signes ne prouvent pas à eux seuls une fuite du joint spi. Si de l’huile réapparaît sur le tube, fais contrôler la fourche, surtout si elle risque d’atteindre le frein ou le pneu.</p></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Passe en revue les tubes et la zone des joints. Une trace d’huile répétée peut indiquer une fuite ; ne roule pas si de l’huile risque d’atteindre le frein ou le pneu.</p><p>Les valeurs, la position de contrôle et les opérations autorisées dépendent du modèle : la notice constructeur reste prioritaire. Moto stable, moteur coupé et refroidi pour les inspections concernées.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Passe en revue les tubes et la zone des joints. Une trace d’huile répétée peut indiquer une fuite ; ne roule pas si de l’huile risque d’atteindre le frein ou le pneu.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/map\">Trouver un atelier pour contrôler la fourche ↗</a></p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(6,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-6\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(6,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-6\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Comprends les deux joints</h4><p>Le cache-poussière protège la zone coulissante des saletés. Le joint spi, situé derrière, retient l’huile de fourche. Ce sont deux éléments distincts.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Poussière ou fuite ?</h4><p>Un tube poussiéreux n’est pas forcément défectueux. Une trace grasse persistante ou une coulure près du joint peut signaler une fuite.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Observe les tubes</h4><p>Rayures, impacts, corrosion ou caoutchouc détérioré peuvent favoriser une fuite. Un choc important peut aussi endommager la suspension sans fuite immédiate.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Quand faire réparer ?</h4><p>Une fuite confirmée nécessite un diagnostic. Si l’huile atteint le pneu ou les freins, n’utilise pas la moto. Le remplacement d’un joint spi est une intervention technique.</p></article></div></details></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Tube piqué ou rayé\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-da04df55dc6a3957-desktop-square.webp\"/><div class=\"content\"><h3>Tube de fourche piqué ou rayé : quels signes surveiller ?</h3><p>Des piqûres, rayures ou traces de corrosion sur la zone de coulissement peuvent détériorer le joint spi. Fais contrôler la fourche si le chrome est endommagé.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Photographie originale : cache-poussière de fourche craquelé et traces grasses autour du joint\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-e83f8ef1c7816175-desktop-square.webp\"/><div class=\"content\"><h3>Joint spi et cache-poussière de fourche : craquelures et traces d’huile</h3><p>Observe les craquelures du caoutchouc, le dépôt noir et les traces grasses autour du tube. Ces signes ne prouvent pas à eux seuls une fuite du joint spi. Si de l’huile réapparaît sur le tube, fais contrôler la fourche, surtout si elle risque d’atteindre le frein ou le pneu.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul aria-label=\"Matériel utile, défilement horizontal\" class=\"accessory-list\" id=\"accessory-carousel-6\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe d’inspection</strong><span>Pour repérer les traces grasses et les impacts.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon microfibre — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Chiffon doux non pelucheux</strong><span>Pour essuyer délicatement la zone accessible.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details></div></details><details class=\"section\" id=\"controle-07\" open=\"\"><summary><span class=\"num\">07</span><span><h2>Avant de partir : les 4 dernières vérifications rapides</h2><span class=\"sub\">Quatre contrôles rapides, comme un tour de moto avant de rouler</span></span></summary><div class=\"layout\"><div class=\"visual-column\"><div class=\"visual\"><img alt=\"Moto roadster noire sans marque sur fond neutre, points de contrôle interactifs\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-1082d06954213ab5-desktop-square.webp\"/><button aria-controls=\"p07-1\" aria-label=\"Ouvrir : Éclairage et signalisation\" class=\"hotspot\" onclick=\"showPopup('p07-1')\" style=\"--x:82%;--y:27%\">1</button><div aria-label=\"Éclairage et signalisation\" class=\"popup\" id=\"p07-1\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-1')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Éclairage et signalisation\" src=\"/images/entretien-moto-guide/controle-21fff2c40492c790.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Comment vérifier les feux stop et clignotants moto seul ?</h3><p>Teste séparément les deux commandes de frein pour vérifier le feu stop. Contrôle aussi les feux avant, les clignotants et l’éclairage de plaque.</p><p style=\"margin-top:12px\">Seul, utilise le reflet sur un mur ou une vitrine, ou filme l’arrière de la moto avec un téléphone posé sur un support stable.</p></div></div><button aria-controls=\"p07-2\" aria-label=\"Ouvrir : Commandes et câbles\" class=\"hotspot\" onclick=\"showPopup('p07-2')\" style=\"--x:53%;--y:27%\">2</button><div aria-label=\"Commandes et câbles\" class=\"popup\" id=\"p07-2\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-2')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Commandes et câbles\" src=\"/images/entretien-moto-guide/controle-518d1180b32daf55.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Accélérateur et commandes moto : vérifier le retour et les points durs</h3><p>À l’arrêt, vérifie que la poignée d’accélérateur revient librement et que les leviers et pédales fonctionnent sans point dur.</p><p style=\"margin-top:12px\">Tourne doucement le guidon de butée à butée, moteur coupé : aucune commande ni aucun câble ne doit accrocher ou se tendre anormalement.</p></div></div><button aria-controls=\"p07-3\" aria-label=\"Ouvrir : Fuites et fixations\" class=\"hotspot\" onclick=\"showPopup('p07-3')\" style=\"--x:43%;--y:66%\">3</button><div aria-label=\"Fuites et fixations\" class=\"popup\" id=\"p07-3\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-3')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Fuites et fixations\" src=\"/images/entretien-moto-guide/controle-b88ac487c4590184.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Fuite d’huile moto : vérifier les traces au sol et les fixations</h3><p>Regarde sous la moto et autour du moteur, des durites et des suspensions. Une trace fraîche de liquide doit être identifiée.</p><p style=\"margin-top:12px\">Une tache au sol ne suffit pas à identifier le liquide. Si tu suspectes une fuite de frein ou une fuite importante, ne prends pas la route.</p></div></div><button aria-controls=\"p07-4\" aria-label=\"Ouvrir : Dernier tour de moto\" class=\"hotspot\" onclick=\"showPopup('p07-4')\" style=\"--x:30%;--y:43%\">4</button><div aria-label=\"Dernier tour de moto\" class=\"popup\" id=\"p07-4\" role=\"group\"><button aria-label=\"Fermer\" class=\"close\" onclick=\"hidePopup('p07-4')\">×</button><div class=\"content\" style=\"padding:22px 14px 12px\"><img alt=\"Dernier tour de moto\" src=\"/images/entretien-moto-guide/controle-38a00b9d519a0972.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><h3>Contrôle avant de rouler : rétroviseurs, bagages et voyants</h3><p>Vérifie les rétroviseurs, les bagages, les éléments visibles mal fixés et les éventuels voyants d’alerte.</p><p style=\"margin-top:12px\">Avant de démarrer, assure-toi qu’aucun objet ne gêne la direction, les roues, les commandes ou la transmission.</p></div></div></div><details class=\"additional-info lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Informations et précautions complémentaires</summary><p>Effectue ces contrôles moto immobilisée, sur un sol stable. Le fonctionnement des feux varie selon les modèles : certains nécessitent le moteur en marche. Pour tester les feux seul, ne laisse pas tourner le moteur dans un espace fermé.</p><p>Si une commande accroche, si un témoin critique reste allumé ou si tu suspectes une fuite de frein, fais contrôler la moto avant de rouler.</p></details></div><div class=\"lm-editorial-advice\"><div class=\"desktop-explain\"><div class=\"lm-visual-label\">Ce que tu peux vérifier</div><p class=\"explain\">Avant de partir : feux, commandes, fuites visibles et derniers éléments à sécuriser. Sélectionne un point orange pour afficher la méthode.</p><p class=\"lm-context-link\"><a href=\"https://labelmoto.fr/info/premiere-moto-accessoires-indispensables-conseils-a2\">Voir les accessoires indispensables à moto ↗</a></p></div><details class=\"technical-detail lm-full-width-detail\" open=\"\"><summary>Conseils pratiques</summary><div class=\"technical-nav\"><button aria-label=\"Conseil précédent\" class=\"technical-arrow\" onclick=\"moveTech(7,-1)\" type=\"button\">‹</button><span aria-live=\"polite\" class=\"technical-counter\" id=\"tech-count-7\">1 / 4</span><button aria-label=\"Conseil suivant\" class=\"technical-arrow\" onclick=\"moveTech(7,1)\" type=\"button\">›</button></div><div aria-label=\"Conseils techniques, défilement horizontal\" class=\"technical-grid\" id=\"tech-carousel-7\" tabindex=\"0\"><article aria-label=\"Conseil 1 sur 4\" class=\"technical-card\"><h4>Éclairage et signalisation</h4><p>Teste le feu stop avec chaque commande. Seul, utilise un reflet sur un mur ou une vidéo sur support stable.</p></article><article aria-label=\"Conseil 2 sur 4\" class=\"technical-card\"><h4>Commandes et câbles</h4><p>Vérifie à l’arrêt le retour libre de l’accélérateur, les leviers et les pédales, sans point dur.</p></article><article aria-label=\"Conseil 3 sur 4\" class=\"technical-card\"><h4>Fuites et fixations</h4><p>Cherche les traces fraîches sous le moteur et près des durites et suspensions. Fais identifier toute fuite suspecte.</p></article><article aria-label=\"Conseil 4 sur 4\" class=\"technical-card\"><h4>Dernier tour de moto</h4><p>Contrôle les rétroviseurs, les bagages, les éléments pendants et les témoins inhabituels.</p></article></div></details></div><div class=\"lm-desktop-illustrated\"><h3>Contrôles illustrés</h3><div aria-label=\"Contrôles illustrés, défilement horizontal\" class=\"lm-desktop-illustrated-track\" tabindex=\"0\"><article class=\"lm-desktop-illustrated-card\"><img alt=\"Éclairage et signalisation\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-21fff2c40492c790-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><div class=\"content\" style=\"padding:22px 14px 12px\"><h3>Comment vérifier les feux stop et clignotants moto seul ?</h3><p>Teste séparément les deux commandes de frein pour vérifier le feu stop. Contrôle aussi les feux avant, les clignotants et l’éclairage de plaque.</p><p style=\"margin-top:12px\">Seul, utilise le reflet sur un mur ou une vitrine, ou filme l’arrière de la moto avec un téléphone posé sur un support stable.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Commandes et câbles\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-518d1180b32daf55-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><div class=\"content\" style=\"padding:22px 14px 12px\"><h3>Accélérateur et commandes moto : vérifier le retour et les points durs</h3><p>À l’arrêt, vérifie que la poignée d’accélérateur revient librement et que les leviers et pédales fonctionnent sans point dur.</p><p style=\"margin-top:12px\">Tourne doucement le guidon de butée à butée, moteur coupé : aucune commande ni aucun câble ne doit accrocher ou se tendre anormalement.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Fuites et fixations\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-b88ac487c4590184-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><div class=\"content\" style=\"padding:22px 14px 12px\"><h3>Fuite d’huile moto : vérifier les traces au sol et les fixations</h3><p>Regarde sous la moto et autour du moteur, des durites et des suspensions. Une trace fraîche de liquide doit être identifiée.</p><p style=\"margin-top:12px\">Une tache au sol ne suffit pas à identifier le liquide. Si tu suspectes une fuite de frein ou une fuite importante, ne prends pas la route.</p></div></article><article class=\"lm-desktop-illustrated-card\"><img alt=\"Dernier tour de moto\" class=\"lm-square-artwork\" loading=\"lazy\" src=\"/images/entretien-moto-guide/controle-38a00b9d519a0972-desktop-square.webp\" style=\"display:block;width:100%;height:auto;max-height:48vh;object-fit:contain;border-radius:12px;margin:0 auto 12px\"/><div class=\"content\" style=\"padding:22px 14px 12px\"><h3>Contrôle avant de rouler : rétroviseurs, bagages et voyants</h3><p>Vérifie les rétroviseurs, les bagages, les éléments visibles mal fixés et les éventuels voyants d’alerte.</p><p style=\"margin-top:12px\">Avant de démarrer, assure-toi qu’aucun objet ne gêne la direction, les roues, les commandes ou la transmission.</p></div></article></div></div><details class=\"accessory-strip accessory-details lm-full-width-detail\" data-always-open=\"true\" onclick='if(event.target.closest(\"summary\")) event.preventDefault()' open=\"\"><summary>Matériel utile pour ce contrôle</summary><ul class=\"accessory-list\" id=\"accessory-carousel-7\" tabindex=\"0\"><li class=\"lm-affiliate-card\"><div aria-label=\"Emplacement pour la photo du produit\" class=\"lm-affiliate-image\">Photo du matériel à ajouter</div><strong>Smartphone et support stable</strong><span>Pour filmer le feu stop lorsque tu es seul.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Référence à renseigner</span><span class=\"lm-affiliate-link-pending\">Lien affilié à ajouter</span></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/lampe-inspection.png\" alt=\"Lampe d’inspection — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Lampe d’inspection</strong><span>Pour observer les zones sombres autour du moteur.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.osram.com/ecat/LEDinspect%20MINI%20140%20ESSENTIAL-LED%20inspection%20lights-Automotive/jp/en/GPS01_35587991/\" target=\"_blank\" rel=\"noopener noreferrer external\">OSRAM · LEDinspect Mini 140</a><a class=\"lm-fabricant-link\" href=\"https://media.ledlenser.com/fileadmin/bilder/Arbeitslicht/i-Serie/iW5R/iW5R_PDS_EN.pdf\" target=\"_blank\" rel=\"noopener noreferrer external\">Ledlenser · iW5R (fiche fabricant PDF)</a></div></div></li><li class=\"lm-affiliate-card\"><div class=\"lm-affiliate-image\"><img src=\"/images/materiel-entretien/chiffon-microfibre.png\" alt=\"Chiffon microfibre — visuel générique\" loading=\"lazy\" style=\"display:block;width:100%;height:100%;max-height:170px;object-fit:contain\"/></div><strong>Chiffon propre</strong><span>Pour distinguer une trace ancienne d’une trace fraîche, sans toucher aux pièces chaudes.</span><div class=\"lm-affiliate-meta\"><span class=\"lm-affiliate-ref\">Références fabricants</span><div class=\"lm-fabricant-links\"><a class=\"lm-fabricant-link\" href=\"https://www.gs27.com/466-microfibre-verte-3352349947070.html\" target=\"_blank\" rel=\"noopener noreferrer external\">GS27 · Microfibre</a><a class=\"lm-fabricant-link\" href=\"https://www.sonax.com/en/care-products/microfibre-cloth-exterior-1-piece-04162000\" target=\"_blank\" rel=\"noopener noreferrer external\">SONAX · Microfibre 40 × 40</a></div></div></li></ul></details></div></details><section class=\"lm-ending lm-ending-final\" aria-label=\"Conclusion de l’article\"><span class=\"lm-final-kicker\">À retenir</span><h2>Inspecter sa moto, c’est déjà mieux la connaître</h2><p>Tu n’as pas besoin d’être mécanicien pour repérer une chaîne anormale, un pneu abîmé, une fuite ou une commande qui fonctionne mal. Le bon réflexe, c’est d’observer régulièrement ta moto et de suivre sa notice, sans improviser de réparation.</p><p>Ces vérifications ne remplacent pas l’entretien prévu par le constructeur. Si un élément de sécurité te semble douteux, ne prends pas de risque : fais contrôler ta moto avant de repartir.</p><p class=\"lm-ending-occasion\" data-lm-occasion-conclusion=\"20261114\">Ces dix contrôles te serviront aussi si tu envisages une moto d’occasion : ils donnent une première idée de son état avant l’achat, sans remplacer l’essai, l’historique d’entretien ni l’avis d’un professionnel.</p><a class=\"lm-occasion-cta\" data-lm-occasion-cta=\"20261114\" href=\"https://labelmoto.fr/info/achat-moto-occasion-guide-complet-pour-eviter-les-pieges\"><span class=\"lm-occasion-cta-text\"><span class=\"lm-occasion-cta-kicker\">Guide d’achat moto d’occasion</span><strong class=\"lm-occasion-cta-title\">Les pièges à éviter avant d’acheter</strong></span><span class=\"lm-occasion-cta-arrow\" aria-hidden=\"true\">→</span></a><div class=\"lm-ending-actions\"><a class=\"lm-primary-link\" href=\"https://labelmoto.fr/map\">Trouver un professionnel sur la carte</a><a class=\"lm-secondary-link\" href=\"https://labelmoto.fr/info/premiere-moto-accessoires-indispensables-conseils-a2\">Découvrir les accessoires indispensables</a></div></section>\n<section class=\"lm-final-faq\" data-lm-final-faq=\"20261114\" aria-labelledby=\"lm-final-faq-desktop\"><div class=\"lm-faq-heading\"><span class=\"lm-final-kicker\">Recherche rapide</span><h2 id=\"lm-final-faq-desktop\">Questions fréquentes</h2><p>Un doute sur un contrôle ? Retrouve l’essentiel en quelques secondes.</p></div><div class=\"lm-faq-list\"><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Faut-il faire les dix contrôles avant chaque trajet ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Pas forcément en détail. Avant de partir, vérifie au minimum l’état visible des pneus, l’absence de fuite, le fonctionnement des feux et des commandes. Pour la pression, la chaîne et les niveaux, suis les indications de ta notice, notamment avant un long trajet ou après une immobilisation.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Peut-on vérifier soi-même la tension de sa chaîne moto ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Oui, moteur coupé et moto stable, sans approcher les doigts du pignon ou de la couronne. Mesure le débattement selon la méthode et la valeur de ton constructeur. Points durs, maillons fissurés ou dents très usées : fais contrôler la transmission avant de rouler.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">À quoi sert le repère TWI sur un pneu moto ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Le repère TWI indique où se trouvent les témoins d’usure dans les rainures. Si la gomme atteint leur niveau, le pneu doit être remplacé. Une coupure, une hernie ou une usure anormale peut aussi imposer un contrôle ou un remplacement avant ce stade.</p><p class=\"lm-faq-source\"><a href=\"https://www.michelin.fr/motorbike/conseils-moto/regles-pneus/profondeur-de-sculpture-des-pneus-moto\" target=\"_blank\" rel=\"noopener noreferrer external\">Comprendre les témoins d’usure avec Michelin ↗</a></p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Peut-on inspecter les plaquettes et les disques sans démontage ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Souvent, un premier contrôle visuel est possible à travers l’étrier. Regarde la garniture des deux plaquettes et cherche des rayures profondes ou des fissures sur le disque. Les limites d’épaisseur dépendent de la moto : si tu vois mal ou si tu as un doute, passe par un professionnel.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Pourquoi le niveau du liquide de frein baisse-t-il ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Quand les plaquettes s’usent, les pistons avancent et le niveau du réservoir peut baisser sans qu’il y ait de fuite. Mais une baisse rapide, une trace de liquide ou un levier spongieux exigent un contrôle. N’ajoute pas de liquide au hasard.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Une huile moteur noire est-elle forcément à remplacer ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Non. La couleur seule ne suffit pas à juger l’huile. Respecte la méthode de lecture du niveau et les intervalles de vidange de ta notice. Une émulsion persistante, des particules inhabituelles, une baisse rapide ou un voyant de pression nécessitent un contrôle.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Comment contrôler le liquide de refroidissement sans danger ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Si ta moto possède un vase d’expansion, vérifie ses repères à froid, dans la position prescrite par le constructeur. N’ouvre jamais le bouchon d’un circuit chaud ou sous pression. Si le niveau baisse régulièrement ou si le moteur surchauffe, fais rechercher la cause.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Quels signes indiquent une batterie moto à surveiller ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Démarreur lent, clic au démarrage ou éclairage qui faiblit peuvent signaler un manque de charge, sans prouver à eux seuls que la batterie est morte. Vérifie aussi l’état visible des cosses et du boîtier. Une batterie gonflée, fissurée ou qui fuit ne doit pas être mise en charge.</p></div></details><details class=\"lm-faq-item\"><summary><span class=\"lm-faq-question\">Quels défauts imposent de faire contrôler la moto avant de rouler ?</span><span aria-hidden=\"true\" class=\"lm-faq-plus\">+</span></summary><div class=\"lm-faq-answer\"><p>Un freinage anormal, une fuite suspecte, un pneu coupé ou déformé, une chaîne endommagée, une fuite importante à la fourche ou un voyant critique sont des signaux d’alerte. En cas de doute sur la sécurité, laisse la moto à l’arrêt et demande l’avis d’un professionnel.</p></div></details></div></section></div></main><footer>Aperçu local autonome · Non publié · Visuels issus des fichiers de travail existants</footer>";


// Visuels approuvés pour l'aperçu natif. La version mobile et ses CTA restent
// intacts, sauf l'image d'huile qui pointait sur un vase de refroidissement.
const imagesGuide = '/images/entretien-moto-guide/';
const huileHublot = `${imagesGuide}huile-moteur-hublot-rond-desktop-square.webp`;
const mobileImageCorrigee = articleMarkupBase.replaceAll(
  `${imagesGuide}controle-cc1948992f27ba22.webp`,
  huileHublot,
);

const debutDesktop = mobileImageCorrigee.indexOf('<div class="lm-desktop-reference">');
const debutArticle = mobileImageCorrigee.slice(0, debutDesktop);
const partieDesktop = mobileImageCorrigee.slice(debutDesktop)
  // Le roadster 4:3 validé remplace le visuel du sommaire sur ordinateur.
  .replace(
    `src="${imagesGuide}controle-1082d06954213ab5.webp"`,
    `src="${imagesGuide}controle-1082d06954213ab5-desktop-square.webp"`,
  )
  // Le hublot d'huile ne doit jamais afficher un vase de refroidissement.
  .replace(
    `src="${imagesGuide}controle-cc1948992f27ba22-desktop-square.webp"`,
    `src="${huileHublot}"`,
  )
  // La brosse est déjà traitée dans la carte nettoyage/lubrification validée.
  .replace(
    /<article class="lm-desktop-illustrated-card lm-original-card"><img alt="Nettoyer la chaîne à la brosse"[\s\S]*?<\/article>/,
    '',
  )
  // Le visuel validé situe désormais la batterie sous la selle OU sur le côté.
  .replace(
    /(<article class="lm-desktop-illustrated-card"><img alt="Photographie originale : batterie située sous la selle"[\s\S]*?<div class="content">)<h3>Repérer la batterie sous la selle<\/h3><p>[\s\S]*?<\/p>/,
    '$1<h3>Où se trouve la batterie sur une moto ?</h3><p>Selon le modèle, elle peut être sous la selle ou derrière un cache latéral. Repère son emplacement sans démonter de pièces sensibles, moteur coupé.</p>',
  )
  // Une seule image validée regroupe les bornes oxydées et le boîtier déformé.
  .replace(
    /<article class="lm-desktop-illustrated-card"><img alt="Oxydation des bornes"[\s\S]*?<\/article>/,
    `<article class="lm-desktop-illustrated-card"><img alt="Inspection de batterie : oxydation des cosses et boîtier déformé" class="lm-square-artwork" loading="lazy" src="${imagesGuide}controle-d0d441c8e24aa386-desktop-square.webp"/><div class="content"><h3>Les signes d'une batterie à surveiller</h3><p>Observe les cosses oxydées, les câbles abîmés, un boîtier gonflé ou fissuré et toute fuite. Un témoin éventuel ne suffit pas à diagnostiquer l'état de la batterie.</p></div></article>`,
  )
  .replace(/<article class="lm-desktop-illustrated-card"><img alt="Déformation du boîtier"[\s\S]*?<\/article>/, '')
  .replace(/<article class="lm-desktop-illustrated-card"><img alt="Témoin visuel"[\s\S]*?<\/article>/, '');

// Les lettres restent du vrai texte HTML/CSS au-dessus des photos originales.
// On conserve ainsi les trois cartes par vue et une nettete identique au site.
const partieDesktopAnnotee = partieDesktop
  .replace(
    /(<img alt="Dommages : coupure, hernie, craquelures"[^>]+\/>)/,
    (_tout, image: string) => `<div class="lm-sharp-visual">${image}<div class="lm-photo-labels lm-photo-damage" aria-hidden="true"><span class="lm-photo-caption"><strong>Coupure</strong></span><span class="lm-photo-caption"><strong>Hernie</strong></span><span class="lm-photo-caption"><strong>Craquelures</strong></span></div></div>`,
  )
  .replace(
    /(<img alt="Usures anormales : centre, épaules et facettes"[^>]+\/>)/,
    (_tout, image: string) => `<div class="lm-sharp-visual">${image}<div class="lm-photo-labels lm-photo-wear" aria-hidden="true"><span class="lm-photo-caption"><strong>Usure au centre</strong><small>Surgonflage possible</small></span><span class="lm-photo-caption"><strong>Usure aux épaules</strong><small>Sous-gonflage possible</small></span><span class="lm-photo-caption"><strong>Usure en facettes</strong><small>Suspension / équilibrage</small></span></div></div>`,
  )
  .replace(
    /(<img alt="Marquage du pneu : 120\/70 R17 58W"[^>]+\/>)/,
    (_tout, image: string) => `<div class="lm-sharp-visual">${image}<div class="lm-twi-inset" aria-hidden="true"><img alt="" loading="lazy" src="${imagesGuide}controle-7fdbe8c96b5b2fe9-desktop-square.webp"/><span>ZOOM TWI</span></div><div class="lm-photo-labels lm-photo-dimensions" aria-hidden="true"><span class="lm-photo-caption"><strong>120</strong><small>Largeur<br/>(mm)</small></span><span class="lm-photo-caption"><strong>70</strong><small>Hauteur<br/>(%)</small></span><span class="lm-photo-caption"><strong>R</strong><small>Radiale</small></span><span class="lm-photo-caption"><strong>17</strong><small>Jante<br/>(po)</small></span><span class="lm-photo-caption"><strong>58</strong><small>Charge<br/>236 kg</small></span><span class="lm-photo-caption"><strong>W</strong><small>Vitesse<br/>270 km/h</small></span></div></div>`,
  )
  // Complément de pédagogie sous la carte marquages/TWI, sur bureau uniquement.
  .replace(
    '<p>Exemple : 120/70 R17 58W. Vérifie les dimensions et les indices homologués pour ta moto.</p></div></article>',
    '<p>Exemple : 120/70 R17 58W. Vérifie les dimensions et les indices homologués pour ta moto.</p><p style="margin-top:12px"><strong>Et le TWI ?</strong> C’est l’abréviation de <em>Tread Wear Indicator</em> (témoin d’usure). Sur le flanc, ce repère indique où trouver les petites barrettes en relief dans les rainures. Quand la gomme atteint leur niveau, il faut remplacer le pneu.</p></div></article>',
  );

const articleMarkupVisuels = (debutArticle + partieDesktopAnnotee).replaceAll(
  '<p><strong>4020</strong> signifie que ce pneu a été fabriqué durant la 40ᵉ semaine de 2020.</p><p>Lors d’un achat d’occasion, vérifie le code de date sur les deux pneus, leur état et les éventuelles craquelures. La date seule ne fixe pas une péremption.</p>',
  '<p><strong>4020</strong> = 40ᵉ semaine de 2020.</p><p>La date ne suffit pas : examine aussi les deux pneus.</p>',
);

// Références partagées avec la page Consommables : fonctionnement inchangé.
import { materielReferences } from "@/lib/materiel-references-fabricants";
const escapeHtml = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
export const articleMarkup = articleMarkupVisuels.replace("<footer>Aperçu local autonome · Non publié · Visuels issus des fichiers de travail existants</footer>", "").replace(/<li class="lm-affiliate-card">[\s\S]*?<\/li>/g, (card) => {
  const match = card.match(/\/images\/materiel-entretien\/([a-z-]+)\.png/);
  if (!match) return card;
  const references = materielReferences[match[1]];
  if (!references || references.length !== 3) return card;
  const links = references.map(ref => `<a class="lm-fabricant-link" href="${escapeHtml(ref.url)}" target="_blank" rel="noopener noreferrer external">${escapeHtml(ref.brand)} · ${escapeHtml(ref.name)}</a>`).join("");
  const section = `<div class="lm-fabricant-links">${links}</div>`;
  if (card.includes('class="lm-fabricant-links"')) {
    return card.replace(/<div class="lm-fabricant-links">[\s\S]*?<\/div>/, section);
  }
  return card;
});
